var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u043e\u0441\u044c \u043d\u0430 6% \u000d\u000a\u0432 \u043c\u0430\u0440\u0442\u0435\u000d\u000a\u0421\u0440\u0435\u0434\u043d\u0435\u0441\u0443\u0442\u043e\u0447\u043d\u044b\u0439 \u0432\u044b\u043f\u0443\u0441\u043a \u0443\u043f\u0430\u043b \u0434\u043e 15,96 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u043f\u0440\u043e\u0442\u0438\u0432 16,99 \u0442\u044b\u0441. \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435 \u2014 \u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u0438 \u0443\u0434\u0430\u0440\u043e\u0432 \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0445 \u0434\u0440\u043e\u043d\u043e\u0432 \u043f\u043e \u000d\u000aEGA \u0438 Alba. \u041d\u0430 \u0440\u0435\u0433\u0438\u043e\u043d \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f 9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430, 15% \u0438\u043c\u043f\u043e\u0440\u0442\u0430 \u0415\u0421 \u0438 20% \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u000d\u000a\u0432 \u0421\u0428\u0410.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u043b \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b \u2014 \u000d\u000a\u043c\u0435\u0434\u0435\u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0432\u043e\u0434\u044b \u0433\u043e\u0442\u043e\u0432\u044f\u0442 \u000d\u000a\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0443\u000d\u000a\u0417\u0430\u043f\u0440\u0435\u0442 \u0432\u0432\u0435\u0434\u0435\u043d \u0432 \u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0435 \u0430\u043f\u0440\u0435\u043b\u044f \u0434\u043b\u044f \u043d\u0443\u0436\u0434 \u000d\u000a\u0430\u0433\u0440\u0430\u0440\u043d\u043e\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430. \u0420\u044f\u0434 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u0443\u0436\u0435 \u043e\u0431\u044a\u044f\u0432\u0438\u043b \u000d\u000a\u043e \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0438 \u043c\u0435\u0434\u0438 \u0438 \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e\u043c \u0432\u044b\u0445\u043e\u0434\u0435 \u000d\u000a\u043d\u0430 \u0442\u0435\u0445\u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u0435, \u0447\u0442\u043e \u0440\u0430\u0437\u0432\u0435\u0440\u043d\u0435\u0442 \u043c\u0430\u0440\u0442\u043e\u0432\u0441\u043a\u0438\u0439 \u000d\u000a\u0440\u0435\u043a\u043e\u0440\u0434 \u0432 \u0440\u0435\u0437\u043a\u043e\u0435 \u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0432\u043e II \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435.\u000d\u000a\u0428\u0430\u043d\u0445\u0430\u0439\u0441\u043a\u0430\u044f \u0431\u0438\u0440\u0436\u0430 \u043e\u0442\u043a\u0440\u044b\u043b\u0430 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u0446\u0430\u043c \u000d\u000a\u0434\u043e\u0441\u0442\u0443\u043f \u043a \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u043c \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u0430\u043c\u000d\u000a\u0422\u043e\u0440\u0433\u0438 \u0441 \u0443\u0447\u0430\u0441\u0442\u0438\u0435\u043c \u043d\u0435\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u043e\u0432 \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u0430\u043b\u0438 \u000d\u000a22 \u0430\u043f\u0440\u0435\u043b\u044f, \u0440\u0430\u0441\u0447\u0435\u0442\u044b \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b \u0432 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u043e\u0439 \u000d\u000a\u0432\u0430\u043b\u044e\u0442\u0435. \u041a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b SHFE (200\u2013400 \u0442\u044b\u0441. \u043b\u043e\u0442\u043e\u0432 \u000d\u000a\u0432 \u0434\u0435\u043d\u044c) \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u043f\u0440\u044f\u043c\u0443\u044e \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u044e \u041b\u043e\u043d\u0434\u043e\u043d\u0441\u043a\u043e\u0439 \u000d\u000a\u0431\u0438\u0440\u0436\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0438 \u0441\u043c\u0435\u0449\u0430\u044e\u0442 \u0446\u0435\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u000d\u000a\u043f\u043e \u043d\u0438\u043a\u0435\u043b\u044e \u0432 \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u0410\u0437\u0438\u0438.\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043b\u0430 \u0432\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043f\u043e\u0448\u043b\u0438\u043d\u044b \u000d\u000a\u0437\u0430 \u043f\u0440\u043e\u0445\u043e\u0434 \u0441\u0443\u0434\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 \u041c\u0430\u043b\u0430\u043a\u043a\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0440 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u041f\u0443\u0440\u0431\u0430\u044f \u042e\u0434\u0445\u0438 \u0421\u0430\u0434\u0435\u0432\u0430 \u043e\u0437\u0432\u0443\u0447\u0438\u043b \u000d\u000a\u0438\u0434\u0435\u044e \u043d\u0430 \u0444\u043e\u0440\u0443\u043c\u0435 \u0432 \u0414\u0436\u0430\u043a\u0430\u0440\u0442\u0435. \u0427\u0435\u0440\u0435\u0437 \u043f\u0440\u043e\u043b\u0438\u0432 \u000d\u000a\u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 40% \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438; \u0421\u0438\u043d\u0433\u0430\u043f\u0443\u0440 \u000d\u000a\u0438 \u041c\u0430\u043b\u0430\u0439\u0437\u0438\u044f \u0438\u043d\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u0443 \u043d\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u043b\u0438, \u000d\u000a\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u044f \u0432\u0441\u0435\u0445 \u0442\u0440\u0435\u0445 \u000d\u000a\u043f\u0440\u0438\u0431\u0440\u0435\u0436\u043d\u044b\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0438 \u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a \u043f\u043e\u0432\u044b\u0441\u0438\u043b\u0438 \u0441\u0442\u0430\u0442\u0443\u0441 \u000d\u000a\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u0434\u043e \u00ab\u0441\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u0430 \u0435\u0434\u0438\u043d\u043e\u0439 \u000d\u000a\u0441\u0443\u0434\u044c\u0431\u044b\u00bb\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0443\u0442\u043e \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u0432\u0438\u0437\u0438\u0442\u0430 \u000d\u000a\u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0414\u0430\u043d\u0438\u044d\u043b\u0430 \u0428\u0430\u043f\u0443 \u0432 \u041f\u0435\u043a\u0438\u043d \u0438 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044e \u000d\u000a\u0426\u0438\u043d\u0445\u0430\u0439. \u041a\u0438\u0442\u0430\u0439 \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u043d\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f \u000d\u000a\u043a \u0433\u0440\u0430\u0444\u0438\u0442\u0443, \u043b\u0438\u0442\u0438\u044e, \u0442\u0438\u0442\u0430\u043d\u0443 \u0438 \u0420\u0417\u041c \u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a\u0430 \u0432 \u043e\u0431\u043c\u0435\u043d \u000d\u000a\u043d\u0430 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0443\u044e \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0438 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u0443\u044e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443.\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043c\u0435\u0434\u0438 \u0432 \u041a\u0438\u0442\u0430\u0435 \u0432 \u043c\u0430\u0440\u0442\u0435 \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0433\u043b\u043e \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430\u000d\u000a\u0412\u044b\u043f\u0443\u0441\u043a \u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b 1,33 \u043c\u043b\u043d \u000d\u000a\u0442\u043e\u043d\u043d \u2014 \u0440\u0435\u043a\u043e\u0440\u0434 \u0441 1990 \u0433\u043e\u0434\u0430. \u0420\u043e\u0441\u0442 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u043b \u0441\u043a\u0430\u0447\u043e\u043a \u000d\u000a\u0446\u0435\u043d \u043d\u0430 \u0441\u0435\u0440\u043d\u0443\u044e \u043a\u0438\u0441\u043b\u043e\u0442\u0443 (\u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u043f\u043b\u0430\u0432\u043a\u0438) \u000d\u000a\u0438\u0437 \u0437\u0430 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u0441\u0435\u0440\u044b \u043d\u0430 \u0444\u043e\u043d\u0435 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u041e\u0440\u043c\u0443\u0437\u0430: \u000d\u000a\u0437\u0430\u0432\u043e\u0434\u044b \u043f\u043e\u043b\u0443\u0447\u0430\u044e\u0442 \u0441\u0432\u044b\u0448\u0435 5 \u0442\u044b\u0441. \u044e\u0430\u043d\u0435\u0439 \u0441 \u0442\u043e\u043d\u043d\u044b \u000d\u000a\u043c\u0435\u0434\u0438 \u043d\u0430 \u043f\u0440\u043e\u0434\u0430\u0436\u0435 \u043a\u0438\u0441\u043b\u043e\u0442\u044b.\u000d\u000aMoody's \u043f\u043e\u043d\u0438\u0437\u0438\u043b\u043e \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043f\u043e \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0443 \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0434\u043e \u00ab\u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e\u00bb\u000d\u000a\u0410\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e \u0443\u043a\u0430\u0437\u0430\u043b\u043e \u043d\u0430 \u0443\u044f\u0437\u0432\u0438\u043c\u043e\u0441\u0442\u044c \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438: \u043f\u043e\u0447\u0442\u0438 \u000d\u000a\u0432\u0435\u0441\u044c \u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0439 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0438\u0434\u0435\u0442 \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432, \u0443\u0433\u043b\u0435\u0432\u043e\u0434\u043e\u0440\u043e\u0434\u044b \u0444\u043e\u0440\u043c\u0438\u0440\u0443\u044e\u0442 \u043e\u043a\u043e\u043b\u043e \u000d\u000a\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b \u0434\u043e\u0445\u043e\u0434\u043e\u0432 \u0431\u044e\u0434\u0436\u0435\u0442\u0430. \u0413\u043e\u0441\u0434\u043e\u043b\u0433 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u000d\u000a\u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c 2025 \u0433\u043e\u0434\u0430 \u2014 147% \u0412\u0412\u041f, \u043e\u0434\u0438\u043d \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u000d\u000a\u0432\u044b\u0441\u043e\u043a\u0438\u0445 \u0432 \u043c\u0438\u0440\u0435.\u000d\u000aCATL \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u043b\u0438\u043d\u0435\u0439\u043a\u0443 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u000d\u000a\u043d\u043e\u0432\u043e\u0433\u043e \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f\u000d\u000a\u041f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0448\u043b\u0430 \u0437\u0430 \u0434\u0435\u043d\u044c \u0434\u043e \u041f\u0435\u043a\u0438\u043d\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0430\u0432\u0442\u043e\u0441\u0430\u043b\u043e\u043d\u0430. \u0411\u0430\u0442\u0430\u0440\u0435\u044f Shenxing III \u0437\u0430\u0440\u044f\u0436\u0430\u0435\u0442\u0441\u044f \u000d\u000a\u0437\u0430 \u0448\u0435\u0441\u0442\u044c \u043c\u0438\u043d\u0443\u0442, \u043c\u043e\u0434\u0435\u043b\u0438 Qilin III \u0438 Condensed \u000d\u000a\u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u044e\u0442 \u043f\u0440\u043e\u0431\u0435\u0433 1500 \u043a\u043c; \u043a \u043a\u043e\u043d\u0446\u0443 2026 \u0433\u043e\u0434\u0430 \u000d\u000aCATL \u043d\u0430\u0447\u043d\u0435\u0442 \u043f\u0435\u0440\u0432\u043e\u0435 \u0432 \u043c\u0438\u0440\u0435 \u043c\u0430\u0441\u0441\u043e\u0432\u043e\u0435 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u0430\u0442\u0440\u0438\u0439\u0438\u043e\u043d\u043d\u044b\u0445 \u0431\u0430\u0442\u0430\u0440\u0435\u0439 Naxtra.\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u0437\u0430\u044f\u0432\u0438\u043b \u043e \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0438\u0438 \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u0433\u043e \u000d\u000a\u0441\u0432\u043e\u043f\u0430 \u043c\u0435\u0436\u0434\u0443 \u0421\u0428\u0410 \u0438 \u041e\u0410\u042d\u000d\u000a\u0413\u043b\u0430\u0432\u0430 \u0426\u0411 \u041e\u0410\u042d \u0425\u0430\u043b\u0435\u0434 \u0411\u0430\u043b\u0430\u043c\u0430 \u0440\u0430\u043d\u0435\u0435 \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u043b \u000d\u000a\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0441 \u043c\u0438\u043d\u0438\u0441\u0442\u0440\u043e\u043c \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u0421\u0428\u0410 \u0421\u043a\u043e\u0442\u0442\u043e\u043c \u000d\u000a\u0411\u0435\u0441\u0441\u0435\u043d\u0442\u043e\u043c \u043a\u0430\u043a \u0441\u0442\u0440\u0430\u0445\u043e\u0432\u043a\u0443 \u043d\u0430 \u0441\u043b\u0443\u0447\u0430\u0439 \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438. \u000d\u000a\u041f\u043e\u0441\u043e\u043b \u041e\u0410\u042d \u042e\u0441\u0435\u0444 \u0430\u043b\u044c-\u041e\u0442\u0435\u0439\u0431\u0430 \u043d\u0430\u0437\u0432\u0430\u043b \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043e \u043f\u043e\u0442\u0440\u0435\u0431\u043d\u043e\u0441\u0442\u0438 \u042d\u043c\u0438\u0440\u0430\u0442\u043e\u0432 \u000d\u000a\u0432\u043e \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u043d\u0435 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u043c\u0438 \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.\u000d\u000aBlueFive Capital \u0438\u0437 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u0430\u0435\u0442 \u000d\u000a$3 \u043c\u043b\u0440\u0434 \u0432 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0439 \u0444\u043e\u043d\u0434\u000d\u000a\u041f\u0435\u0440\u0432\u044b\u0439 \u0442\u0440\u0430\u043d\u0448 \u043e\u043a\u043e\u043b\u043e $1 \u043c\u043b\u0440\u0434 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u000d\u000a\u043a III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0443 2026 \u0433\u043e\u0434\u0430. \u0424\u043e\u043d\u0434 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u000d\u000a\u043d\u0430 \u0440\u043e\u0441\u0442 \u0432\u043e\u0435\u043d\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u0441\u0442\u0440\u0430\u043d \u0417\u0430\u043b\u0438\u0432\u0430 \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0441 \u0418\u0440\u0430\u043d\u043e\u043c \u0438 \u0441\u0444\u043e\u043a\u0443\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u000d\u000a\u043d\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u0445 \u0441\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0430\u043c\u0438 \u041d\u0410\u0422\u041e.\u000d\u000a01 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u043b\u0438\u0432\u0430 \u0432 \u043c\u0430\u0440\u0442\u0435 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u043e\u0441\u044c \u043d\u0430 6%\u000d\u000a28 \u0444\u0435\u0432\u0440\u0430\u043b\u044f \u0421\u0428\u0410 \u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u044c \u043d\u0430\u0447\u0430\u043b\u0438 \u0432\u043e\u0439\u043d\u0443 \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0440\u0430\u043d\u0430. \u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435, \u0438\u0441\u043b\u0430\u043c\u0441\u043a\u0430\u044f \u000d\u000a\u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u043b \u0431\u043e\u043b\u044c\u0448\u0443\u044e \u000d\u000a\u0447\u0430\u0441\u0442\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0441\u044b\u0440\u044c\u044f \u0438 \u044d\u043d\u0435\u0440\u0433\u043e\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u0435\u0439.\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u043b\u0438\u0432\u0430 \u0432 \u043c\u0430\u0440\u0442\u0435 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u043e\u0441\u044c \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u0440\u0435\u0433\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0449\u0435\u0439\u0441\u044f \u000d\u000a\u0431\u043b\u043e\u043a\u0430\u0434\u044b \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0435\u0442\u0435 \u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u0438\u043d\u0441\u0442\u0438\u0442\u0443\u0442\u0430 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f. \u000a\u000d\u000a\u0421\u0440\u0435\u0434\u043d\u0435\u0441\u0443\u0442\u043e\u0447\u043d\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u000d\u000a\u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0432 \u043c\u0430\u0440\u0442\u0435 \u0441\u043d\u0438\u0437\u0438\u043b\u043e\u0441\u044c \u000d\u000a\u043d\u0430 6% \u2014 \u0434\u043e 15,963 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043f\u0440\u043e\u0442\u0438\u0432 16,997 \u0442\u044b\u0441. \u000d\u000a\u0442\u043e\u043d\u043d \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u0438\u043d\u0441\u0442\u0438\u0442\u0443\u0442 \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u000d\u000a\u0438 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0438 \u0431\u0443\u0434\u0443\u0442 \u043e\u0449\u0443\u0449\u0430\u0442\u044c \u0435\u0449\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u043c\u0435\u0441\u044f\u0446\u0435\u0432. \u000a\u000d\u000a\u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u0441\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u043b\u0438 \u043e\u043a\u043e\u043b\u043e 6,5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u000d\u000a(9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043e\u0431\u044a\u0435\u043c\u0430). \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0430 \u0440\u0435\u0433\u0438\u043e\u043d \u000d\u000a\u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043e\u043a\u043e\u043b\u043e 15% \u0438\u043c\u043f\u043e\u0440\u0442\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u000d\u000a\u0432 \u0415\u0421 \u0438 \u043e\u043a\u043e\u043b\u043e 20% \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0432 \u0421\u0428\u0410.\u000a\u000d\u000a\u0418\u0437-\u0437\u0430 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0435 \u0437\u0430\u0432\u043e\u0434\u044b \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435 \u0432\u044b\u043d\u0443\u0436\u0434\u0435\u043d\u044b \u000d\u000a\u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432\u0430\u0442\u044c \u0438\u043c\u0435\u044e\u0449\u0438\u0435\u0441\u044f \u0437\u0430\u043f\u0430\u0441\u044b \u0441\u044b\u0440\u044c\u044f. \u000d\u000a\u0417\u0430\u043a\u0440\u044b\u0442\u0438\u0435 \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u043d\u0430\u0440\u0443\u0448\u0438\u043b\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0431\u043e\u043a\u0441\u0438\u0442\u043e\u0432 \u0438 \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u0430, \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u0445 \u0434\u043b\u044f \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f. \u000a\u000d\u000a\u0412 \u043d\u0430\u0447\u0430\u043b\u0435 \u043c\u0430\u0440\u0442\u0430 \u0434\u0432\u0430 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435 \u2014 \u000d\u000a\u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Global Aluminium \u000d\u000a\u0438 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f Aluminium Bahrain \u2014 \u000d\u000a\u043f\u043e\u0434\u0432\u0435\u0440\u0433\u043b\u0438\u0441\u044c \u0443\u0434\u0430\u0440\u0430\u043c \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0445 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432. \u000d\u000a\u041e\u0431\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0431\u044b\u043b\u0438 \u0432\u044b\u043d\u0443\u0436\u0434\u0435\u043d\u044b \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0438 \u043e\u0431\u044a\u044f\u0432\u0438\u0442\u044c \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 \u000d\u000a\u043f\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u043c.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000a\u0428\u0432\u0435\u0439\u0446\u0430\u0440\u0438\u044f \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u000d\u000a\u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043e\u0441\u0442\u0430\u0432\u0430\u043b\u0441\u044f \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u043e\u0439 \u0421\u043e\u0432\u0435\u0442\u0430 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u0430\u0440\u0430\u0431\u0441\u043a\u0438\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u0441 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0443 \u0428\u0432\u0435\u0439\u0446\u0430\u0440\u0438\u0438 \u0434\u043e \u0441\u0438\u0445 \u043f\u043e\u0440 \u043d\u0435 \u0431\u044b\u043b\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u000d\u000a\u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439.\u000d\u000a\u0428\u0432\u0435\u0439\u0446\u0430\u0440\u0438\u044f \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u000d\u000a\u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u043e\u0442 \u043f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0440\u0438\u0441\u043a\u043e\u0432, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0434\u0438\u0441\u043a\u0440\u0438\u043c\u0438\u043d\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u043c\u0435\u0440\u044b \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0438\u043d\u0441\u0442\u0438\u0442\u0443\u0442\u043e\u0432 \u0438 \u043d\u0435\u0437\u0430\u043a\u043e\u043d\u043d\u0443\u044e \u000d\u000a\u044d\u043a\u0441\u043f\u0440\u043e\u043f\u0440\u0438\u0430\u0446\u0438\u044e. \u041e\u0431 \u044d\u0442\u043e\u043c \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u000d\u000a\u0448\u0432\u0435\u0439\u0446\u0430\u0440\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430.\u000a\u000d\u000a\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0442\u0430\u043a\u0436\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0432\u043e\u0434 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u043f\u043b\u0430\u0442\u0435\u0436\u0435\u0439 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043c\u044f \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u0430\u043c\u0438. \u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u000d\u000a\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0441\u043f\u043e\u0440\u043e\u0432, \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u044b \u0441\u043c\u043e\u0433\u0443\u0442 \u043f\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0442\u044c \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0435 \u0440\u0430\u0437\u043d\u043e\u0433\u043b\u0430\u0441\u0438\u044f \u043d\u0430 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0438\u0435 \u000d\u000a\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u0430\u0440\u0431\u0438\u0442\u0440\u0430\u0436\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u0431\u0443\u043d\u0430\u043b\u0430.\u000a\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u0431\u044b\u043b\u043e \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d\u043e \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u043e\u043c \u000d\u000a\u0428\u0432\u0435\u0439\u0446\u0430\u0440\u0438\u0438 \u0413\u0438 \u041f\u0430\u0440\u043c\u0435\u043b\u0435\u043d\u043e\u043c \u0438 \u043c\u0438\u043d\u0438\u0441\u0442\u0440\u043e\u043c \u000d\u000a\u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0448\u0435\u0439\u0445\u043e\u043c \u0421\u0430\u043b\u044c\u043c\u0430\u043d\u043e\u043c \u0431\u0435\u043d \u000d\u000a\u0425\u0430\u043b\u0438\u0444\u043e\u0439 \u0410\u043b\u044c \u0425\u0430\u043b\u0438\u0444\u043e\u0439 \u043d\u0430 \u043f\u043e\u043b\u044f\u0445 \u0432\u0435\u0441\u0435\u043d\u043d\u0435\u0439 \u000d\u000a\u0441\u0435\u0441\u0441\u0438\u0438 \u0412\u0441\u0435\u043c\u0438\u0440\u043d\u043e\u0433\u043e \u0431\u0430\u043d\u043a\u0430 \u0438 \u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u000d\u000a\u0432\u0430\u043b\u044e\u0442\u043d\u043e\u0433\u043e \u0444\u043e\u043d\u0434\u0430 \u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d\u0435.\u000d\u000a02 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aMoody\u2019s \u0443\u0445\u0443\u0434\u0448\u0438\u043b\u043e \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043f\u043e \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0443 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u000d\u000a\u0434\u043e \u00ab\u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e\u00bb \u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u0432\u0441\u0442\u0443\u043f\u0438\u043b \u0432 \u043d\u044b\u043d\u0435\u0448\u043d\u0438\u0439 \u043a\u0440\u0438\u0437\u0438\u0441 \u0441 \u0443\u0436\u0435 \u0432\u044b\u0441\u043e\u043a\u043e\u0439 \u0434\u043e\u043b\u0433\u043e\u0432\u043e\u0439 \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u043e\u0439. \u041f\u043e \u0438\u0442\u043e\u0433\u0430\u043c 2025 \u0433\u043e\u0434\u0430 \u000d\u000a\u0433\u043e\u0441\u0434\u043e\u043b\u0433 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u043b\u0441\u044f \u0432 147% \u0412\u0412\u041f \u2014 \u043e\u0434\u0438\u043d \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0432\u044b\u0441\u043e\u043a\u0438\u0445 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0435\u0439 \u0432 \u043c\u0438\u0440\u0435.\u000d\u000a\u0410\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e Moody\u2019s \u0443\u0445\u0443\u0434\u0448\u0438\u043b\u043e \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u000d\u000a\u043f\u043e \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0443 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0441\u043e \u00ab\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0433\u043e\u00bb \u000d\u000a\u0434\u043e \u00ab\u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e\u00bb \u043d\u0430 \u0444\u043e\u043d\u0435 \u0431\u043b\u0438\u0436\u043d\u0435\u0432\u043e\u0441\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0432\u043b\u0438\u044f\u043d\u0438\u0435 \u000d\u000a\u043d\u0430 \u0441\u043b\u0430\u0431\u044b\u0435 \u0431\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0435 \u0438 \u0434\u043e\u043b\u0433\u043e\u0432\u044b\u0435 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0438 \u000d\u000a\u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430. \u000a\u000d\u000a\u041f\u043e\u0447\u0442\u0438 \u0432\u0441\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0439 \u043d\u0435\u0444\u0442\u0438 \u043f\u0440\u043e\u0445\u043e\u0434\u044f\u0442 \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432, \u0430 \u0434\u043e\u0445\u043e\u0434\u044b \u043e\u0442 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u000d\u000a\u0443\u0433\u043b\u0435\u0432\u043e\u0434\u043e\u0440\u043e\u0434\u043e\u0432 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u044e\u0442 \u043e\u043a\u043e\u043b\u043e \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b \u000d\u000a\u0431\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0445 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0439. \u041f\u043e \u043e\u0446\u0435\u043d\u043a\u0435 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0430, \u000d\u000a\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u043e\u0441\u0442\u0430\u0435\u0442\u0441\u044f \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u000d\u000a\u0443\u044f\u0437\u0432\u0438\u043c\u043e\u0439 \u043f\u0435\u0440\u0435\u0434 \u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u043f\u0435\u0440\u0435\u0431\u043e\u044f\u043c\u0438 \u000d\u000a\u0432 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435 \u0438 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0435 \u044d\u043d\u0435\u0440\u0433\u043e\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u0435\u0439.\u000d\u000a\u0410\u043d\u0430\u043b\u0438\u0442\u0438\u043a\u0438 Moody\u2019s \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u0438\u0432\u0430\u044e\u0442, \u0447\u0442\u043e \u0431\u043b\u043e\u043a\u0430\u0434\u0430 \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u0430\u0432\u0438\u0430\u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435 \u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u043e \u000d\u000a\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u043d\u0435\u0444\u0442\u044f\u043d\u043e\u043c \u0438 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u043c \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043d\u0430 \u0442\u0443\u0440\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c \u0441\u0435\u043a\u0442\u043e\u0440\u0435. \u000d\u000a\u042d\u0442\u043e \u0432 \u0441\u0432\u043e\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u000d\u000a\u043d\u0430 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0444\u0438\u043d\u0430\u043d\u0441\u044b \u0438 \u0432\u0430\u043b\u044e\u0442\u043d\u044b\u0435 \u000d\u000a\u0440\u0435\u0437\u0435\u0440\u0432\u044b \u0441\u0442\u0440\u0430\u043d\u044b. \u000a\u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c Moody\u2019s \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u043e \u0434\u043e\u043b\u0433\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u0435 \u000d\u000a\u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0432 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u0438 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u0430\u0445, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0440\u0435\u0439\u0442\u0438\u043d\u0433 \u000d\u000a\u043d\u0435\u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u0434\u043e\u043b\u0433\u0430 \u0432 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u0435 \u000d\u000a\u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u00abB2\u00bb.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u041e\u0410\u042d \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u043c \u000d\u000a\u0441\u0432\u043e\u043f\u0435 \u043d\u0430 20 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432\u000d\u000a\u041e\u0410\u042d \u0432\u0445\u043e\u0434\u044f\u0442 \u0432 \u0442\u0440\u043e\u0439\u043a\u0443 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u043e\u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430. \u041f\u043e \u0438\u0442\u043e\u0433\u0430\u043c 2024 \u0433\u043e\u0434\u0430 \u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u044b \u0432\u043b\u043e\u0436\u0438\u043b\u0438 \u0432 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0443\u044e \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0443 \u043e\u043a\u043e\u043b\u043e 16,5 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($4,49 \u043c\u043b\u0440\u0434) \u000d\u000a\u0438 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u043b\u0438 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 10% \u0432\u0441\u0435\u0445 \u043f\u0440\u044f\u043c\u044b\u0445 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0432 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e.\u000d\u000a\u0426\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0435 \u0431\u0430\u043d\u043a\u0438 \u041e\u0410\u042d \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b\u0438 \u000d\u000a\u043f\u044f\u0442\u0438\u043b\u0435\u0442\u043d\u0435\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u043c \u0441\u0432\u043e\u043f\u0435, \u000d\u000a\u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0449\u0435\u0435 \u043e\u0431\u043c\u0435\u043d \u043d\u0430 \u0441\u0443\u043c\u043c\u0443 \u2028\u000d\u000a\u0434\u043e 20 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($5,44 \u043c\u043b\u0440\u0434). \u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d \u043d\u0430 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u000d\u000a\u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0432\u0430\u043b\u044e\u0442 \u0432\u043e \u0432\u0437\u0430\u0438\u043c\u043d\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435 \u000d\u000a\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u044f\u0445, \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u000d\u000a\u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u043e\u0433\u043e \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u0430.\u000d\u000a\u041c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u0433\u043e \u0441\u0432\u043e\u043f\u0430 \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0431\u0430\u043d\u043a\u0430\u043c \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u043f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0442\u044c \u000d\u000a\u0434\u0438\u0440\u0445\u0430\u043c\u044b \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e, \u043c\u0438\u043d\u0443\u044f \u0440\u044b\u043d\u043e\u043a, \u0441\u043d\u0438\u0436\u0430\u044f \u0442\u0435\u043c \u000d\u000a\u0441\u0430\u043c\u044b\u043c \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u0442 \u043a\u043e\u043b\u0435\u0431\u0430\u043d\u0438\u0439 \u043e\u0431\u043c\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043a\u0443\u0440\u0441\u0430. \u042d\u0442\u043e \u0442\u0430\u043a\u0436\u0435 \u043f\u043e\u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0434\u043e\u043b\u043b\u0430\u0440\u0430 \u0432 \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0445 \u000d\u000a\u0440\u0430\u0441\u0447\u0435\u0442\u0430\u0445 \u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u044c \u000d\u000a\u0432 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0432\u0430\u043b\u044e\u0442\u0430\u0445.\u000d\u000a03 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u0437\u0430\u044f\u0432\u0438\u043b \u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u0433\u043e \u0441\u0432\u043e\u043f\u0430 \u000d\u000a\u043c\u0435\u0436\u0434\u0443 \u0421\u0428\u0410 \u0438 \u041e\u0410\u042d\u000d\u000a\u0412\u0435\u0440\u043e\u044f\u0442\u043d\u043e\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u043c \u0441\u0432\u043e\u043f\u0435 \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435. \u041e\u0410\u042d \u000d\u000a\u0431\u043e\u043b\u044c\u0448\u0435 \u0434\u0440\u0443\u0433\u0438\u0445 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u043f\u043e\u0434\u0432\u0435\u0440\u0433\u0430\u043b\u0438\u0441\u044c \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u043c \u0443\u0434\u0430\u0440\u0430\u043c. \u0426\u0435\u043b\u044f\u043c\u0438 \u0430\u0442\u0430\u043a \u000d\u000a\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0438\u0441\u044c \u043f\u043e\u0440\u0442\u044b, \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430, \u0434\u0430\u0442\u0430-\u0446\u0435\u043d\u0442\u0440\u044b \u0438 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u044b, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0437\u0430\u0432\u043e\u0434 Emirates Global Aluminium.\u000d\u000a\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0421\u0428\u0410 \u0414\u043e\u043d\u0430\u043b\u044c\u0434 \u0422\u0440\u0430\u043c\u043f \u0437\u0430\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u000d\u000a\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u041e\u0410\u042d, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0437\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u043e \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u043c \u000d\u000a\u0441\u0432\u043e\u043f\u0435.\u000a\u000d\u000a\u041a\u0430\u043a \u0441\u043e\u043e\u0431\u0449\u0430\u043b\u0430 \u0440\u0430\u043d\u0435\u0435 \u0433\u0430\u0437\u0435\u0442\u0430 The Wall Street \u000d\u000aJournal, \u0433\u043b\u0430\u0432\u0430 \u0426\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0431\u0430\u043d\u043a\u0430 \u041e\u0410\u042d \u0425\u0430\u043b\u0435\u0434 \u000d\u000a\u041c\u0443\u0445\u0430\u043c\u043c\u0435\u0434 \u0411\u0430\u043b\u0430\u043c\u0430 \u043f\u043e\u0434\u043d\u0438\u043c\u0430\u043b \u0432\u043e\u043f\u0440\u043e\u0441 \u043e \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u043c \u000d\u000a\u0441\u0432\u043e\u043f\u0435 \u043d\u0430 \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0445 \u0441 \u043c\u0438\u043d\u0438\u0441\u0442\u0440\u043e\u043c \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u0421\u0428\u0410 \u000d\u000a\u0421\u043a\u043e\u0442\u0442\u043e\u043c \u0411\u0435\u0441\u0441\u0430\u043d\u0442\u043e\u043c. \u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0438\u0437\u0434\u0430\u043d\u0438\u044f, \u0442\u0430\u043a\u043e\u0439 \u000d\u000a\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u043b\u0441\u044f \u043d\u0430 \u0441\u043b\u0443\u0447\u0430\u0439, \u0435\u0441\u043b\u0438 \u0432\u043e\u0439\u043d\u0430 \u000d\u000a\u043f\u0440\u0438\u0432\u0435\u0434\u0435\u0442 \u043a \u0431\u043e\u043b\u0435\u0435 \u0441\u0435\u0440\u044c\u0435\u0437\u043d\u043e\u043c\u0443 \u043a\u0440\u0438\u0437\u0438\u0441\u0443 \u000d\u000a\u0432 \u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u043e\u0439 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0435.\u000a\u000d\u000a\u0412\u043c\u0435\u0441\u0442\u0435 \u0441 \u0442\u0435\u043c \u043f\u043e\u0441\u043e\u043b \u041e\u0410\u042d \u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d\u0435 \u042e\u0441\u0435\u0444 \u000d\u000a\u0430\u043b\u044c-\u041e\u0442\u0435\u0439\u0431\u0430 \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u043d\u0443\u043b, \u0447\u0442\u043e \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u043e\u0441\u0442\u0430\u0435\u0442\u0441\u044f \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0439. \u00ab\u041b\u044e\u0431\u044b\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u000d\u000a\u043e \u0442\u043e\u043c, \u0447\u0442\u043e \u041e\u0410\u042d \u043d\u0443\u0436\u0434\u0430\u044e\u0442\u0441\u044f \u0432\u043e \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u000d\u000a\u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435, \u043d\u0435\u0432\u0435\u0440\u043d\u043e \u043e\u0442\u0440\u0430\u0436\u0430\u044e\u0442 \u000d\u000a\u0444\u0430\u043a\u0442\u044b\u00bb, \u2014 \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u0430.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0438 \u0418\u043e\u0440\u0434\u0430\u043d\u0438\u044f \u043f\u043e\u0441\u0442\u0440\u043e\u044f\u0442 \u000d\u000a\u0442\u0440\u0430\u043d\u0441\u0433\u0440\u0430\u043d\u0438\u0447\u043d\u0443\u044e \u0436\u0435\u043b\u0435\u0437\u043d\u0443\u044e \u0434\u043e\u0440\u043e\u0433\u0443\u000d\u000a\u0412 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u044c \u0442\u043e\u0432\u0430\u0440\u043e\u043e\u0431\u043e\u0440\u043e\u0442\u0430 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043c\u044f \u0441\u0442\u0440\u0430\u043d\u0430\u043c\u0438 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u000d\u000a\u0430\u0432\u0442\u043e\u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043e\u043c \u0447\u0435\u0440\u0435\u0437 \u0441\u0443\u0445\u043e\u043f\u0443\u0442\u043d\u0443\u044e \u0433\u0440\u0430\u043d\u0438\u0446\u0443. \u0416\u0435\u043b\u0435\u0437\u043d\u0430\u044f \u0434\u043e\u0440\u043e\u0433\u0430 \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0443\u0441\u043a\u043e\u0440\u0438\u0442\u044c \u000d\u000a\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044e \u0438 \u0441\u043d\u0438\u0437\u0438\u0442\u044c \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u0438\u0437\u0434\u0435\u0440\u0436\u043a\u0438.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0438 \u0418\u043e\u0440\u0434\u0430\u043d\u0438\u044f \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u000d\u000a\u043d\u0430\u0447\u0430\u0442\u044c \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0443 \u043a \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u000d\u000a\u0434\u043e\u0440\u043e\u0433\u0438, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442 \u0434\u0432\u0435 \u0441\u0442\u0440\u0430\u043d\u044b, \u2014 \u044d\u0442\u043e \u000d\u000a\u0443\u043a\u0440\u0435\u043f\u0438\u0442 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0446\u0435\u043f\u043e\u0447\u043a\u0438 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435. \u000a\u000d\u000a\u041a\u0430\u043a \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e \u0438\u043e\u0440\u0434\u0430\u043d\u0441\u043a\u043e\u0435 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e Petra, \u000d\u000a\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u044b \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0430 \u0434\u0432\u0443\u0445 \u0441\u0442\u0440\u0430\u043d \u043f\u0440\u043e\u0432\u0435\u043b\u0438 \u000d\u000a\u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b, \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u043f\u0440\u0438\u043d\u044f\u043b\u0438 \u000d\u000a\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u044b\u0439 \u043a\u043e\u043c\u0438\u0442\u0435\u0442 \u0434\u043b\u044f \u000d\u000a\u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0442\u0440\u0430\u043d\u0441\u0433\u0440\u0430\u043d\u0438\u0447\u043d\u043e\u0433\u043e \u000d\u000a\u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0430. \u041f\u0440\u043e\u0435\u043a\u0442 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u043c\u043e\u0433\u0443\u0442 \u0438\u043d\u0442\u0435\u0433\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0439 \u0441\u0435\u0442\u044c\u044e \u000d\u000a\u0421\u0438\u0440\u0438\u0438.\u000d\u000a\u041d\u043e\u0432\u043e\u0435 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0442 \u000d\u000a\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u043e\u0435 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0439 \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0432 \u0441\u0430\u043c\u043e\u0439 \u0418\u043e\u0440\u0434\u0430\u043d\u0438\u0438. \u0420\u0430\u043d\u0435\u0435 \u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Jordan Phosphate \u000d\u000aMines \u0438 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438 \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0435 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u0434\u043e\u0440\u043e\u0433\u0438 \u000d\u000a\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e $2,3 \u043c\u043b\u0440\u0434, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442 \u0442\u0440\u0438 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0444\u043e\u0441\u0444\u0430\u0442\u043d\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u044b \u0441 \u043f\u043e\u0440\u0442\u043e\u043c \u0410\u043a\u0430\u0431\u0430.\u000d\u000a04 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 #\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f\u000d\u000a\u0418\u043d\u0432\u0435\u0441\u0442\u0444\u043e\u043d\u0434 \u0438\u0437 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u0442 $3 \u043c\u043b\u0440\u0434 \u000d\u000a\u0432 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u0443\u044e \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c\u000d\u000a\u0422\u043e\u043b\u044c\u043a\u043e \u0432 \u043f\u0435\u0440\u0432\u044b\u0435 48 \u0447\u0430\u0441\u043e\u0432 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435 \u0441\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u000d\u000a\u043f\u043e\u0442\u0440\u0430\u0442\u0438\u043b\u0438 \u043c\u0438\u043b\u043b\u0438\u0430\u0440\u0434\u044b \u0434\u043e\u043b\u043b\u0430\u0440\u043e\u0432 \u043d\u0430 \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0430\u0442\u0430\u043a \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432 \u0438 \u0440\u0430\u043a\u0435\u0442 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0418\u0440\u0430\u043d\u0430.\u000d\u000a\u0411\u0430\u0437\u0438\u0440\u0443\u044e\u0449\u0430\u044f\u0441\u044f \u0432 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000aBlueFive Capital \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u044c \u043e\u043a\u043e\u043b\u043e \u000d\u000a$3 \u043c\u043b\u0440\u0434 \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0444\u043e\u043d\u0434\u0430, \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0443 \u0441 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u043c\u0438 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c\u0438. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e Bloomberg \u000d\u000a\u0441\u043e \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u043d\u0430 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438.\u000a\u000d\u000a\u041d\u0430 \u043f\u0435\u0440\u0432\u043e\u043c \u044d\u0442\u0430\u043f\u0435 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0435\u043a\u0442\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u000d\u000a\u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044f \u0443\u0436\u0435 \u043a III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0443 2026 \u0433\u043e\u0434\u0430, \u043e\u0431\u044a\u0435\u043c\u000d\u000a\u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430 \u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u000d\u000a\u043e\u043a\u043e\u043b\u043e $1 \u043c\u043b\u0440\u0434. \u0424\u043e\u043d\u0434 \u043d\u0430\u043c\u0435\u0440\u0435\u043d \u0432\u043e\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u000d\u000a\u0432\u0435\u0440\u043e\u044f\u0442\u043d\u044b\u043c \u0440\u043e\u0441\u0442\u043e\u043c \u0432\u043e\u0435\u043d\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u000d\u000a\u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435. \u041d\u043e\u0432\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0438\u0442\u0441\u044f \u000d\u000a\u043d\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u0445, \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u000d\u000a\u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0430\u043c \u041d\u0410\u0422\u041e.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043e\u0442 \u0421\u0428\u0410 \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u000d\u000a\u043a \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u0430\u043c \u0441 \u0418\u0440\u0430\u043d\u043e\u043c, \u043e\u043f\u0430\u0441\u0430\u044f\u0441\u044c \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u043f\u0430\u0441\u0430\u0435\u0442\u0441\u044f \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0442\u0438\u044f \u0411\u0430\u0431-\u044d\u043b\u044c-\u041c\u0430\u043d\u0434\u0435\u0431\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u0432\u0430\u0436\u043d\u043e\u0433\u043e \u0434\u043b\u044f \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043d\u0435\u0444\u0442\u0438 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0430. \u041e\u0434\u0438\u043d \u0438\u0437 \u043f\u0440\u043e\u0442\u044f\u0436\u0435\u043d\u043d\u044b\u0445 \u0431\u0435\u0440\u0435\u0433\u043e\u0432\u044b\u0445 \u0443\u0447\u0430\u0441\u0442\u043a\u043e\u0432 \u0432\u0431\u043b\u0438\u0437\u0438 \u043d\u0435\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u044e\u0442 \u0439\u0435\u043c\u0435\u043d\u0441\u043a\u0438\u0435 \u0445\u0443\u0441\u0438\u0442\u044b \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0438 \u0418\u0440\u0430\u043d\u0430. \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u000d\u000a\u043d\u0430 \u0421\u0428\u0410, \u0442\u0440\u0435\u0431\u0443\u044f \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u043a \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u0430\u043c \u000d\u000a\u0441 \u0418\u0440\u0430\u043d\u043e\u043c \u0438 \u043e\u0442\u043a\u0430\u0437\u0430\u0442\u044c\u0441\u044f \u043e\u0442 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u043f\u043e\u0440\u0442\u043e\u0432 \u000d\u000a\u0438\u0441\u043b\u0430\u043c\u0441\u043a\u043e\u0439 \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u0433\u0430\u0437\u0435\u0442\u0430 \u000d\u000aThe Wall Street Journal. \u041d\u0435\u0434\u0430\u0432\u043d\u043e \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e, \u000d\u000a\u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0443 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430, \u000d\u000a\u0441\u0443\u043c\u0435\u043b\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u043d\u0435\u0444\u0442\u0438 \u000d\u000a\u0434\u043e \u0434\u043e\u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u0443\u0440\u043e\u0432\u043d\u044f, \u043f\u0435\u0440\u0435\u043f\u0440\u0430\u0432\u043b\u044f\u044f \u0441\u044b\u0440\u0443\u044e \u000d\u000a\u043d\u0435\u0444\u0442\u044c \u0447\u0435\u0440\u0435\u0437 \u043f\u0443\u0441\u0442\u044b\u043d\u044e \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435. \u000a\u000d\u000a\u0419\u0435\u043c\u0435\u043d\u0441\u043a\u0438\u0435 \u0445\u0443\u0441\u0438\u0442\u044b, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u044e\u0449\u0438\u0435 \u043f\u043e\u0431\u0435\u0440\u0435\u0436\u044c\u0435 \u000d\u000a\u041a\u0440\u0430\u0441\u043d\u043e\u0433\u043e \u043c\u043e\u0440\u044f \u0438 \u0411\u0430\u0431-\u044d\u043b\u044c-\u041c\u0430\u043d\u0434\u0435\u0431\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432, \u000d\u000a\u0437\u0430\u0432\u0435\u0440\u0438\u043b\u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0443\u044e \u0410\u0440\u0430\u0432\u0438\u044e, \u0447\u0442\u043e \u0435\u0435 \u0441\u0443\u0434\u0430 \u000d\u000a\u043d\u0435 \u0431\u0443\u0434\u0443\u0442 \u043f\u043e\u0434\u0432\u0435\u0440\u0433\u0430\u0442\u044c\u0441\u044f \u0430\u0442\u0430\u043a\u0430\u043c. \u0412 \u0442\u043e \u0436\u0435 \u0432\u0440\u0435\u043c\u044f \u000d\u000a\u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0435 \u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u044b \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0438 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u000d\u000a\u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438, \u0447\u0442\u043e \u0445\u0443\u0441\u0438\u0442\u044b \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u044b \u0431\u043e\u043b\u0435\u0435 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u043d\u043e \u0432\u043c\u0435\u0448\u0430\u0442\u044c\u0441\u044f \u0432 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442, \u0435\u0441\u043b\u0438 \u0418\u0440\u0430\u043d \u0443\u0441\u0438\u043b\u0438\u0442 \u000d\u000a\u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435. \u0419\u0435\u043c\u0435\u043d\u0441\u043a\u0438\u0435 \u043f\u043e\u0432\u0441\u0442\u0430\u043d\u0446\u044b \u0442\u0430\u043a\u0436\u0435 \u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u043d\u0430\u0447\u0430\u0442\u044c \u0432\u0437\u0438\u043c\u0430\u0442\u044c \u0441 \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u0435\u0432 \u0441\u0443\u0434\u043e\u0432 \u043f\u043b\u0430\u0442\u0443 \u000d\u000a\u0437\u0430 \u043f\u0440\u043e\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 \u0411\u0430\u0431-\u044d\u043b\u044c-\u041c\u0430\u043d\u0434\u0435\u0431\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432.\u000a\u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0434\u043e \u0432\u043e\u0439\u043d\u044b \u000d\u000a\u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435 \u0431\u044b\u043b \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u0433\u043b\u0430\u0432\u043d\u044b\u0445 \u000d\u000a\u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u0432 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043d\u0435\u0444\u0442\u0438, \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0442 \u0418\u0440\u0430\u043d\u043e\u043c \u000d\u000a\u0441 \u043a\u043e\u043d\u0446\u0430 \u0444\u0435\u0432\u0440\u0430\u043b\u044f. \u041f\u043e\u0441\u043b\u0435 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u0432\u0448\u0438\u0445\u0441\u044f \u000d\u000a\u0431\u0435\u0437\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043d\u043e \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u043e\u0432 \u0432 \u0418\u0441\u043b\u0430\u043c\u0430\u0431\u0430\u0434\u0435 \u000d\u000a\u0414\u043e\u043d\u0430\u043b\u044c\u0434 \u0422\u0440\u0430\u043c\u043f \u043e\u0431\u044a\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0435 \u000d\u000a\u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u0441\u0438\u043b\u044b \u00ab\u043d\u0430\u0447\u043d\u0443\u0442 \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0441\u0435 \u0431\u0435\u0437 \u000d\u000a\u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u0441\u0443\u0434\u0430, \u043f\u044b\u0442\u0430\u044e\u0449\u0438\u0435\u0441\u044f \u0432\u043e\u0439\u0442\u0438 \u000d\u000a\u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432 \u0438\u043b\u0438 \u0432\u044b\u0439\u0442\u0438 \u0438\u0437 \u043d\u0435\u0433\u043e\u00bb. \u000d\u000a\u041f\u043e\u0437\u0436\u0435 \u0426\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0435 \u043a\u043e\u043c\u0430\u043d\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u0421\u0428\u0410 \u000d\u000a\u043f\u043e\u044f\u0441\u043d\u0438\u043b\u043e, \u0447\u0442\u043e \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0431\u0443\u0434\u0443\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0443\u0434\u0430, \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0435\u0441\u044f \u0432 \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0435 \u043f\u043e\u0440\u0442\u044b.\u000d\u000a05 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u0435 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0423\u043a\u0440\u0430\u0438\u043d\u0430 \u0432\u0435\u0434\u0435\u0442 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u0441 \u041e\u043c\u0430\u043d\u043e\u043c, \u041a\u0443\u0432\u0435\u0439\u0442\u043e\u043c \u000d\u000a\u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c \u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u0432 \u0441\u0444\u0435\u0440\u0435 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u0423\u043a\u0440\u0430\u0438\u043d\u0430 \u0432\u0435\u0434\u0435\u0442 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u0441 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c, \u041a\u0443\u0432\u0435\u0439\u0442\u043e\u043c \u0438 \u041e\u043c\u0430\u043d\u043e\u043c \u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u0432 \u0441\u0444\u0435\u0440\u0435 \u000d\u000a\u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0435 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u0430\u043c. \u041e\u0431 \u044d\u0442\u043e\u043c \u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0423\u043a\u0440\u0430\u0438\u043d\u044b \u0412\u043b\u0430\u0434\u0438\u043c\u0438\u0440 \u0417\u0435\u043b\u0435\u043d\u0441\u043a\u0438\u0439.\u000d\u000a\u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u043c\u0435\u0441\u044f\u0446\u0435 \u043e\u043d \u043f\u043e\u0441\u0435\u0442\u0438\u043b \u0440\u044f\u0434 \u0441\u0442\u0440\u0430\u043d \u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442\u044c \u000d\u000a\u0443\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u0438\u0435 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438 \u0438 \u043e\u043f\u044b\u0442 \u0431\u043e\u0440\u044c\u0431\u044b \u000d\u000a\u0441 \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u043c\u0438 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u0430\u043c\u0438. \u0423\u043a\u0440\u0430\u0438\u043d\u0430 \u0443\u0436\u0435 \u000d\u000a\u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0430 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u000d\u000a\u0432 \u0441\u0444\u0435\u0440\u0435 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0441 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0435\u0439 \u000d\u000a\u0438 \u041a\u0430\u0442\u0430\u0440\u043e\u043c, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 \u043f\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0435\u0439 \u0441 \u041e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u043d\u044b\u043c\u0438 \u0410\u0440\u0430\u0431\u0441\u043a\u0438\u043c\u0438 \u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0430\u043c\u0438. \u0421\u0435\u0439\u0447\u0430\u0441 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442\u0441\u044f \u000d\u000a\u0441 \u041e\u043c\u0430\u043d\u043e\u043c, \u041a\u0443\u0432\u0435\u0439\u0442\u043e\u043c \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c.\u000d\u000a\u0423\u043a\u0440\u0430\u0438\u043d\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0431\u043e\u043b\u0435\u0435 \u000d\u000a200 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u043e\u0432, \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u0432\u0448\u0438\u0445 \u0432 \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u0438 \u000d\u000a\u0430\u0442\u0430\u043a \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0445 \u0434\u0430\u043b\u044c\u043d\u043e\u0431\u043e\u0439\u043d\u044b\u0445 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432 \u000d\u000aShahed. \u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0417\u0435\u043b\u0435\u043d\u0441\u043a\u043e\u0433\u043e, \u0443\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u0438\u0435 \u000d\u000a\u0441\u0438\u043b\u044b \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043b\u0438 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0447\u0438\u043a\u0438 \u000d\u000a\u0438 \u043f\u0440\u043e\u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043b\u0438, \u0447\u0442\u043e \u0434\u043b\u044f \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0442\u0430\u043a\u0438\u043c \u0443\u0433\u0440\u043e\u0437\u0430\u043c \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b \u000d\u000a\u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f, \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0432 \u0441\u0444\u0435\u0440\u0435 \u000d\u000a\u0440\u0430\u0434\u0438\u043e\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u043e\u0439 \u0431\u043e\u0440\u044c\u0431\u044b.\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041e\u0410\u042d \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u043b\u0438 \u043f\u043e\u0447\u0442\u0438 80% \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0430\u043d\u0433\u043e\u043b\u044c\u0441\u043a\u0438\u0445 \u000d\u000a\u0430\u043b\u043c\u0430\u0437\u043e\u0432 \u0432 2025 \u0433\u043e\u0434\u0443\u000d\u000a\u0410\u043d\u0433\u043e\u043b\u0430 \u043d\u0430\u0440\u0430\u0449\u0438\u0432\u0430\u0435\u0442 \u0434\u043e\u0431\u044b\u0447\u0443 \u0430\u043b\u043c\u0430\u0437\u043e\u0432 \u0441 \u043a\u043e\u043d\u0446\u0430 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u043a\u043e\u0439 \u0432\u043e\u0439\u043d\u044b \u0432 2002 \u0433\u043e\u0434\u0443. \u0412\u043c\u0435\u0441\u0442\u0435 \u0441 \u0442\u0435\u043c \u000d\u000a\u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u0430\u043b\u043c\u0430\u0437\u043e\u0432 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u0442\u0441\u044f \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u0446\u0435\u043d \u0438 \u0440\u043e\u0441\u0442 \u043f\u043e\u043f\u0443\u043b\u044f\u0440\u043d\u043e\u0441\u0442\u0438 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043a\u0430\u043c\u043d\u0435\u0439.\u000d\u000a\u0414\u043e\u0431\u044b\u0447\u0430 \u043d\u0435\u043e\u0431\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u043d\u044b\u0445 \u0430\u043b\u043c\u0430\u0437\u043e\u0432 \u0432 \u0410\u043d\u0433\u043e\u043b\u0435 \u000d\u000a\u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0432 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u043d\u0430 8% \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u000d\u000a\u0441 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u043c \u0433\u043e\u0434\u043e\u043c \u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 15,19 \u043c\u043b\u043d \u043a\u0430\u0440\u0430\u0442, \u000d\u000a\u043f\u0440\u0435\u0432\u044b\u0441\u0438\u0432 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c \u0432 14,8 \u043c\u043b\u043d \u043a\u0430\u0440\u0430\u0442. \u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043f\u043e\u0447\u0442\u0438 80% \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043f\u0440\u0438\u0448\u043b\u043e\u0441\u044c \u043d\u0430 \u041e\u0410\u042d. \u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0433\u043e\u0441\u0441\u0435\u043a\u0440\u0435\u0442\u0430\u0440\u044f \u043f\u043e \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u043c \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043c \u0410\u043d\u0433\u043e\u043b\u044b \u0416\u0430\u043d\u0438\u0443 \u041a\u043e\u0440\u0440\u0435\u0430 \u0412\u0438\u043a\u0442\u043e\u0440\u0430, \u000d\u000a\u043d\u0430 \u041e\u0410\u042d \u043f\u0440\u0438\u0448\u043b\u043e\u0441\u044c 78,6% \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u000d\u000a\u0430\u043b\u043c\u0430\u0437\u043e\u0432. \u000a\u000d\u000a\u0412\u0442\u043e\u0440\u043e\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0430\u043b\u043c\u0430\u0437\u043e\u0432 \u000d\u000a\u0437\u0430\u043d\u044f\u043b\u0430 \u0411\u0435\u043b\u044c\u0433\u0438\u044f, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u043b\u0430 19,9% \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a. \u042d\u0442\u0438 \u0434\u0432\u0435 \u0441\u0442\u0440\u0430\u043d\u044b \u043e\u0441\u0442\u0430\u043b\u0438\u0441\u044c \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u043c\u0438 \u000d\u000a\u0440\u044b\u043d\u043a\u0430\u043c\u0438 \u0441\u0431\u044b\u0442\u0430 \u0434\u043b\u044f \u0430\u043b\u043c\u0430\u0437\u043d\u043e\u0439 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u0410\u043d\u0433\u043e\u043b\u044b. \u000d\u000a\u041e\u0431\u044a\u0435\u043c \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0430\u043b\u043c\u0430\u0437\u043e\u0432 \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b 17 \u043c\u043b\u043d \u043a\u0430\u0440\u0430\u0442, \u000d\u000a\u0430 \u0435\u0433\u043e \u043e\u0431\u0449\u0430\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0430 $1,6 \u043c\u043b\u0440\u0434. \u000d\u000a\u0412\u0438\u043a\u0442\u043e\u0440 \u043e\u0442\u043c\u0435\u0442\u0438\u043b, \u0447\u0442\u043e \u043e\u0431\u044a\u0435\u043c \u0440\u0435\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u000d\u000a\u0432 2025 \u0433\u043e\u0434\u0443 \u0430\u043b\u043c\u0430\u0437\u043e\u0432 \u0432\u044b\u0440\u043e\u0441 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 70% \u000d\u000a\u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u0441 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u043c \u0433\u043e\u0434\u043e\u043c, \u0442\u043e\u0433\u0434\u0430 \u043a\u0430\u043a \u000d\u000a\u0432\u0430\u043b\u043e\u0432\u0430\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430\u0441\u044c \u043b\u0438\u0448\u044c \u043d\u0430 6,7%.\u000a\u000d\u000a\u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0441\u043b\u043e\u0436\u043d\u0443\u044e \u043a\u043e\u043d\u044a\u044e\u043d\u043a\u0442\u0443\u0440\u0443, \u0430\u043d\u0433\u043e\u043b\u044c\u0441\u043a\u0438\u0435 \u000d\u000a\u0432\u043b\u0430\u0441\u0442\u0438 \u0441\u0447\u0438\u0442\u0430\u044e\u0442, \u0447\u0442\u043e \u0441\u0442\u0440\u0430\u043d\u0430 \u0443\u043a\u0440\u0435\u043f\u043b\u044f\u0435\u0442 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u000d\u000a\u043d\u0430 \u043c\u0438\u0440\u043e\u0432\u043e\u043c \u0440\u044b\u043d\u043a\u0435 \u0438 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u000d\u000a\u043d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u0437\u043d\u0430\u0447\u0438\u043c\u044b\u0445 \u0438\u0433\u0440\u043e\u043a\u043e\u0432 \u0432 \u0430\u043b\u043c\u0430\u0437\u043d\u043e\u0439 \u000d\u000a\u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0438. \u041d\u0430 \u044d\u0442\u043e\u043c \u0444\u043e\u043d\u0435 \u0410\u043d\u0433\u043e\u043b\u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043a\u0443\u043f\u0438\u0442\u044c \u2028\u000d\u000a\u043e\u0442 20 \u0434\u043e 30% \u0432 \u0430\u043b\u043c\u0430\u0437\u043d\u043e\u043c \u043f\u043e\u0434\u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0438 \u000d\u000aAnglo American \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 De Beers.\u000d\u000a06 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u0435 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u0432\u044b\u0437\u0432\u0430\u043b \u043f\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0433\u043e \u0432 \u0434\u0435\u043b\u0430\u0445 \u0418\u0440\u0430\u043a\u0430 \u2028\u000d\u000a\u0438\u0437-\u0437\u0430 \u0430\u0442\u0430\u043a \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432\u000d\u000a\u0420\u0430\u043d\u0435\u0435 \u0430\u043d\u0430\u043b\u043e\u0433\u0438\u0447\u043d\u044b\u0439 \u0448\u0430\u0433 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u044f\u043b\u0430 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f. \u041e\u0431\u0435 \u0441\u0442\u0440\u0430\u043d\u044b \u0432\u044b\u0440\u0430\u0437\u0438\u043b\u0438 \u043f\u0440\u043e\u0442\u0435\u0441\u0442 \u000d\u000a\u0432 \u0441\u0432\u044f\u0437\u0438 \u0441 \u0430\u0442\u0430\u043a\u0430\u043c\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435, \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e, \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0441 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0418\u0440\u0430\u043a\u0430, \u000d\u000a\u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0435 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 \u0421\u0428\u0410 \u0438 \u0418\u0440\u0430\u043d\u043e\u043c.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u0434\u0435\u043b \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u000d\u000a\u0432\u044b\u0437\u0432\u0430\u043b\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0433\u043e \u0432 \u0434\u0435\u043b\u0430\u0445 \u000d\u000a\u0418\u0440\u0430\u043a\u0430 \u0432 \u0441\u0432\u044f\u0437\u0438 \u0441 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0449\u0438\u043c\u0438\u0441\u044f \u0430\u0442\u0430\u043a\u0430\u043c\u0438 \u000d\u000a\u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432. \u041f\u043e \u0432\u0435\u0440\u0441\u0438\u0438 \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u0430, \u000d\u000a\u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043f\u043e\u0434\u0432\u0435\u0440\u0433\u0430\u0435\u0442\u0441\u044f \u0443\u0434\u0430\u0440\u0430\u043c, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u043d\u0430\u043d\u043e\u0441\u044f\u0442 \u0441 \u0438\u0440\u0430\u043a\u0441\u043a\u043e\u0439 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u000d\u000a\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u044b\u0435 \u0418\u0440\u0430\u043d\u043e\u043c \u0433\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0438.\u000d\u000a\u041a\u0430\u043a \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0435 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e, \u000d\u000a\u0438\u0440\u0430\u043a\u0441\u043a\u043e\u043c\u0443 \u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u0443 \u0431\u044b\u043b\u0430 \u0432\u0440\u0443\u0447\u0435\u043d\u0430 \u000d\u000a\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u0430\u044f \u043d\u043e\u0442\u0430 \u043f\u0440\u043e\u0442\u0435\u0441\u0442\u0430. \u0412\u043b\u0430\u0441\u0442\u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u000d\u000a\u043f\u0440\u0438\u0437\u0432\u0430\u043b\u0438 \u0418\u0440\u0430\u043a \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u0441\u0440\u043e\u0447\u043d\u044b\u0435 \u043c\u0435\u0440\u044b \u000d\u000a\u0434\u043b\u044f \u0443\u0441\u0442\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0443\u0433\u0440\u043e\u0437. \u0412 \u043d\u043e\u0442\u0435 \u0442\u0430\u043a\u0436\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u043e, \u000d\u000a\u0447\u0442\u043e \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0437\u0430 \u0441\u043e\u0431\u043e\u0439 \u043f\u0440\u0430\u0432\u043e \u000d\u000a\u043d\u0430 \u043e\u0442\u0432\u0435\u0442\u043d\u044b\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0411\u043e\u0442\u0441\u0432\u0430\u043d\u0430 \u0438 \u041e\u043c\u0430\u043d \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u000d\u000a\u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u0432 \u0441\u0444\u0435\u0440\u0435 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445\u000d\u000a\u0412\u0438\u0437\u0438\u0442 \u0433\u043b\u0430\u0432 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u043b \u043d\u0430\u043a\u0430\u043d\u0443\u043d\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f \u0441\u0440\u043e\u043a\u0430 \u043f\u043e\u0434\u0430\u0447\u0438 \u0437\u0430\u044f\u0432\u043e\u043a \u043d\u0430 \u043f\u043e\u043a\u0443\u043f\u043a\u0443 85% \u000d\u000a\u0430\u043a\u0446\u0438\u0439 \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u0438 De Beers \u043e\u0434\u043d\u043e\u0433\u043e \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0432 \u043c\u0438\u0440\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0430\u043b\u043c\u0430\u0437\u043e\u0432. \u0420\u0430\u043d\u0435\u0435 \u000d\u000a\u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0411\u043e\u0442\u0441\u0432\u0430\u043d\u044b \u0437\u0430\u044f\u0432\u043b\u044f\u043b, \u0447\u0442\u043e \u0441\u0442\u0440\u0430\u043d\u0430 \u0432\u0435\u0434\u0435\u0442 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u0441 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u043c \u0444\u043e\u043d\u0434\u043e\u043c \u041e\u043c\u0430\u043d\u0430 \u000d\u000a\u043e \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0438 \u044d\u0442\u043e\u0439 \u043f\u043e\u043a\u0443\u043f\u043a\u0438.\u000d\u000a\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0411\u043e\u0442\u0441\u0432\u0430\u043d\u044b \u0414\u0443\u043c\u0430 \u0411\u043e\u043a\u043e \u043f\u0440\u043e\u0432\u0435\u043b \u000d\u000a\u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u0441 \u0441\u0443\u043b\u0442\u0430\u043d\u043e\u043c \u041e\u043c\u0430\u043d\u0430 \u0425\u0430\u0439\u0441\u0430\u043c\u043e\u043c \u0431\u0435\u043d \u000d\u000a\u0422\u0430\u0440\u0438\u043a\u043e\u043c \u0410\u043b\u044c \u0421\u0430\u0438\u0434\u043e\u043c \u0432 \u041c\u0430\u0441\u043a\u0430\u0442\u0435. \u041f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u000d\u000a\u0432\u0441\u0442\u0440\u0435\u0447\u0438 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438 \u0440\u044f\u0434 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0439, \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u043d\u0430 \u0443\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u0435 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0430.\u000a\u000d\u000a\u0412 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438, \u043b\u0438\u0434\u0435\u0440\u044b \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u000d\u000a\u043e \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0435, \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0432\u043b\u0430\u0441\u0442\u0438 \u0411\u043e\u0442\u0441\u0432\u0430\u043d\u044b \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u044b \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0433\u0435\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0440\u0430\u0431\u043e\u0442\u044b \u000d\u000a\u0432 \u043c\u0430\u043b\u043e\u0438\u0437\u0443\u0447\u0435\u043d\u043d\u044b\u0445 \u0440\u0430\u0439\u043e\u043d\u0430\u0445 \u043d\u0430 70% \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u044b.\u000a\u000d\u000a\u0411\u043e\u0442\u0441\u0432\u0430\u043d\u0430 \u0441\u0442\u0440\u0435\u043c\u0438\u0442\u0441\u044f \u0434\u0438\u0432\u0435\u0440\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u000d\u000a\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0443, \u0437\u0430\u0432\u0438\u0441\u044f\u0449\u0443\u044e \u043e\u0442 \u0434\u043e\u0431\u044b\u0447\u0438 \u0430\u043b\u043c\u0430\u0437\u043e\u0432, \u000d\u000a\u0437\u0430 \u0441\u0447\u0435\u0442 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u043c\u0435\u0434\u0438, \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0440\u0443\u0434\u044b. \u0414\u043e\u0445\u043e\u0434\u044b \u043e\u0442 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u0430\u043b\u043c\u0430\u0437\u043e\u0432, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043e\u0431\u044b\u0447\u043d\u043e \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u044e\u0442 \u043e\u043a\u043e\u043b\u043e \u0442\u0440\u0435\u0442\u0438 \u000d\u000a\u0433\u043e\u0441\u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0439, \u0441\u043d\u0438\u0437\u0438\u043b\u0438\u0441\u044c \u043d\u0430 \u0444\u043e\u043d\u0435 \u043e\u0441\u043b\u0430\u0431\u043b\u0435\u043d\u0438\u044f \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u0440\u044b\u043d\u043a\u0430. \u000d\u000a07 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aEGA \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 \u043f\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u043c \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u0443\u0434\u0430\u0440\u0430 \u043f\u043e \u0437\u0430\u0432\u043e\u0434\u0443\u000d\u000aAl Taweelah \u2014 \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0445 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043e\u0432 \u0432 \u043c\u0438\u0440\u0435. \u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u000d\u000a\u043e\u043d \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u043b 1,6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f.\u000d\u000aEmirates Global Aluminium (EGA) \u2014 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u000d\u000a\u0432 \u041e\u0410\u042d \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u2014 \u043e\u0431\u044a\u044f\u0432\u0438\u043b \u000d\u000a\u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 \u043f\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u043c \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0445 \u0432\u0438\u0434\u043e\u0432 \u000d\u000a\u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u044f \u0437\u0430\u0432\u043e\u0434\u0430 \u000d\u000aAl Taweelah \u0432 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u0438\u0440\u0430\u043d\u0441\u043a\u043e\u0439 \u000d\u000a\u0430\u0442\u0430\u043a\u0438 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432. \u000a\u000d\u000aEGA \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u043e\u043c\u0443 The National, \u000d\u000a\u0447\u0442\u043e \u00ab\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0432\u0441\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0435 \u0434\u043b\u044f \u000d\u000a\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432 \u0432 \u044d\u0442\u043e\u0442 \u0441\u043b\u043e\u0436\u043d\u044b\u0439 \u043f\u0435\u0440\u0438\u043e\u0434\u00bb. \u000d\u000a\u0417\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043e\u0431\u044a\u0435\u043c\u044b \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u000d\u000a\u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 \u0441\u0442\u0440\u0430\u043d\u044b, \u0447\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u000d\u000a\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430.\u000d\u000a\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0432 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043d\u044f\u0442\u044c \u0434\u043e \u0433\u043e\u0434\u0430. \u0417\u0430\u0432\u043e\u0434 \u000d\u000a\u0432 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0437\u043e\u043d\u0435 KEZAD \u0442\u0430\u043a\u0436\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u043b \u000d\u000a\u0441\u0435\u0440\u044c\u0435\u0437\u043d\u044b\u0435 \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u044f \u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u0430\u0442\u0430\u043a\u0438 \u000d\u000a28 \u043c\u0430\u0440\u0442\u0430. \u041f\u043e\u0441\u043b\u0435 \u043d\u0435\u0435 \u0431\u044b\u043b\u0438 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u000d\u000a\u044d\u0432\u0430\u043a\u0443\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u043b\u0438\u0442\u0435\u0439\u043d\u044b\u0439 \u0438 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043b\u0438\u0437\u043d\u044b\u0439 \u0446\u0435\u0445\u0430, \u000d\u000a\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u0441\u0442\u0430\u043d\u0446\u0438\u044f, \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u043d\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 \u000d\u000a\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441. \u0412\u0441\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u044b \u000d\u000a\u043f\u0435\u0440\u0435\u0432\u0435\u0434\u0435\u043d\u044b \u0432 \u0430\u0432\u0430\u0440\u0438\u0439\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c.\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u041c\u0412\u0424 \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0434\u0438\u043b \u043e \u0440\u0435\u0437\u043a\u043e\u043c \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u0438 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438 \u000d\u000a\u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435 \u0438\u0437-\u0437\u0430 \u0432\u043e\u0439\u043d\u044b\u000d\u000a\u0412 \u0431\u0430\u0437\u043e\u0432\u043e\u043c \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442 \u043a\u0440\u0430\u0442\u043a\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u0438 19-\u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u043e\u0435 \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435 \u0446\u0435\u043d \u043d\u0430 \u044d\u043d\u0435\u0440\u0433\u043e\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u0438, \u0442\u0435\u043c\u043f\u044b \u0440\u043e\u0441\u0442\u0430 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438 \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u0437\u0430\u043c\u0435\u0434\u043b\u044f\u0442\u0441\u044f \u000d\u000a\u0441 3,6% \u0434\u043e 1,9%. \u0412 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u043c \u0433\u043e\u0434\u0443 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0434\u043e 4,6%.\u000d\u000a\u042d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438 \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u0432 2026 \u0433\u043e\u0434\u0443 \u000d\u000a\u0441\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u0441\u044f \u0441 \u0440\u0435\u0437\u043a\u0438\u043c \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u0435\u043c \u0440\u043e\u0441\u0442\u0430 \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u0432\u043e\u0439\u043d\u044b \u0441 \u0418\u0440\u0430\u043d\u043e\u043c, \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u000d\u000a\u0432 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u043c \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 \u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u000d\u000a\u0432\u0430\u043b\u044e\u0442\u043d\u043e\u0433\u043e \u0444\u043e\u043d\u0434\u0430 (\u041c\u0412\u0424). \u000a\u000d\u000a\u0424\u043e\u043d\u0434 \u043e\u0436\u0438\u0434\u0430\u0435\u0442 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u000d\u000a\u043f\u0440\u043e\u0433\u043d\u043e\u0437\u043e\u0432 \u043f\u043e \u0440\u043e\u0441\u0442\u0443 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a \u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430. \u041d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u0441\u0438\u043b\u044c\u043d\u043e\u0435 \u000d\u000a\u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043b\u044f \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430, \u000d\u000a\u0418\u0440\u0430\u043d\u0430, \u0418\u0440\u0430\u043a\u0430, \u041a\u0443\u0432\u0435\u0439\u0442\u0430 \u0438 \u041a\u0430\u0442\u0430\u0440\u0430, \u0442\u043e\u0433\u0434\u0430 \u043a\u0430\u043a \u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f \u0434\u043b\u044f \u041e\u0410\u042d, \u041e\u043c\u0430\u043d\u0430 \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438 \u0431\u0443\u0434\u0443\u0442 \u043c\u0435\u043d\u0435\u0435 \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u043d\u044b\u043c\u0438.\u000a\u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u041c\u0412\u0424 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u0443\u0436\u0435 \u2028\u000d\u000a\u0432 2027 \u0433\u043e\u0434\u0443 \u0432\u0441\u0435 \u044d\u0442\u0438 \u0441\u0442\u0440\u0430\u043d\u044b \u0441\u043c\u043e\u0433\u0443\u0442 \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u000d\u000a\u043a \u0431\u043e\u043b\u0435\u0435 \u0432\u044b\u0441\u043e\u043a\u0438\u043c \u0442\u0435\u043c\u043f\u0430\u043c \u0440\u043e\u0441\u0442\u0430, \u0435\u0441\u043b\u0438 \u0434\u043e\u0431\u044b\u0447\u0430 \u000d\u000a\u0438 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0430 \u0443\u0433\u043b\u0435\u0432\u043e\u0434\u043e\u0440\u043e\u0434\u043e\u0432 \u0431\u0443\u0434\u0443\u0442 \u000d\u000a\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0438\u0445 \u043c\u0435\u0441\u044f\u0446\u0435\u0432.\u000a\u000d\u000a\u0414\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0431\u043b\u043e\u043a\u0430\u0434\u0430 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0438 \u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0438\u0435 \u0443\u0434\u0430\u0440\u044b \u043f\u043e \u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0439 \u000d\u000a\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430\u043c \u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u043f\u0440\u0438\u0432\u0435\u0441\u0442\u0438 \u043a \u0435\u0449\u0435 \u0431\u043e\u043b\u0435\u0435 \u0441\u0435\u0440\u044c\u0435\u0437\u043d\u044b\u043c \u000d\u000a\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f\u043c \u0434\u043b\u044f \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u000d\u000a\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438. \u000a\u000d\u000a\u0424\u0430\u043a\u0442\u043e\u0440\u043e\u043c \u0440\u0438\u0441\u043a\u0430 \u041c\u0412\u0424 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0439 \u0440\u043e\u0441\u0442 \u000d\u000a\u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u043f\u043e\u0441\u043b\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430. \u0414\u0430\u043d\u043d\u0430\u044f \u000d\u000a\u043c\u0435\u0440\u0430 \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u0430 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u000d\u000a\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c, \u043e\u0434\u043d\u0430\u043a\u043e \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u0432\u043e\u0435\u043d\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u0443\u0441\u0438\u043b\u0438\u0442 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u043e\u0435 \u000d\u000a\u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0438 \u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u0440\u0430\u0441\u0445\u043e\u0434\u044b \u000d\u000a\u043d\u0430 \u0441\u043e\u0446\u0438\u0430\u043b\u043a\u0443.\u000d\u000a08 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u043f\u044f\u0442\u044c \u043d\u043e\u0432\u044b\u0445 \u2028\u000d\u000a\u0436/\u0434 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u0432\u000d\u000a\u041f\u043e\u0441\u043b\u0435 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435 \u0447\u0430\u0441\u0442\u044c \u0433\u0440\u0443\u0437\u043e\u0432 \u0431\u044b\u043b\u0430 \u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0430 \u000d\u000a\u043d\u0430 \u0434\u0440\u0443\u0433\u0438\u0435 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b, \u0432 \u043f\u0435\u0440\u0432\u0443\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u0447\u0435\u0440\u0435\u0437 \u043f\u043e\u0440\u0442 \u0414\u0436\u0438\u0434\u0434\u044b.\u000d\u000a\u0413\u043e\u0441\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Saudi Arabia Railways (SAR) \u000d\u000a\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430 \u043f\u044f\u0442\u044c \u043d\u043e\u0432\u044b\u0445 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u0432 \u000d\u000a\u0434\u043b\u044f \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438 \u0446\u0435\u043f\u043e\u0447\u0435\u043a \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0438 \u0438\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u0440\u0430\u0437\u043b\u0438\u0447\u043d\u044b\u0445 \u0432\u0438\u0434\u043e\u0432 \u000d\u000a\u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0435 \u000d\u000a\u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e \u043f\u0435\u0447\u0430\u0442\u0438.\u000a\u000d\u000a\u041d\u043e\u0432\u044b\u0435 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u044e\u0442 \u043f\u043e\u0440\u0442\u044b \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0441 \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u043c\u0438 \u000d\u000a\u0438 \u0441\u0435\u0432\u0435\u0440\u043d\u044b\u043c\u0438 \u0440\u0435\u0433\u0438\u043e\u043d\u0430\u043c\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u0432\u044b\u0445\u043e\u0434\u044f\u0442 \u043a \u043f\u043e\u0440\u0442\u0430\u043c \u041a\u0440\u0430\u0441\u043d\u043e\u0433\u043e \u043c\u043e\u0440\u044f \u0438 \u0441\u043e\u0441\u0435\u0434\u043d\u0438\u043c \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u0430\u043c. \u041f\u0440\u043e\u0435\u043a\u0442 \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u043f\u0435\u0440\u0435\u0431\u043e\u0435\u0432 \u0432 \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435, \u000d\u000a\u0432\u044b\u0437\u0432\u0430\u043d\u043d\u044b\u0445 \u0431\u043b\u043e\u043a\u0430\u0434\u043e\u0439 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0418\u0440\u0430\u043d\u0430.\u000a\u000d\u000a\u0416\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u0430\u044f \u0441\u0435\u0442\u044c \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043a\u0443 \u000d\u000a\u043d\u0435\u0444\u0442\u0435\u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u000d\u000a\u0441\u044b\u0440\u044c\u044f \u0447\u0435\u0440\u0435\u0437 \u0441\u0443\u0445\u043e\u0439 \u043f\u043e\u0440\u0442 \u042d\u0440-\u0420\u0438\u044f\u0434\u0430 \u0438 \u0433\u0440\u0443\u0437\u043e\u0432\u044b\u0435 \u000d\u000a\u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u044b \u0432 \u0414\u0430\u043c\u043c\u0430\u043c\u0435, \u0414\u0436\u0443\u0431\u0435\u0439\u043b\u0435, \u0420\u0430\u0441-\u044d\u043b\u044c-\u0425\u0430\u0439\u0440\u0435, \u000d\u000a\u042d\u043b\u044c-\u0425\u0430\u0440\u0434\u0436\u0435, \u0425\u0430\u0438\u043b\u0435 \u0438 \u042d\u043b\u044c-\u041a\u0443\u0440\u0430\u0439\u044f\u0442\u0435. \u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u000d\u000a\u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u044c \u043f\u0440\u043e\u043c\u0446\u0435\u043d\u0442\u0440\u044b \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u0441 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u043c\u0438 \u043c\u043e\u0440\u0441\u043a\u0438\u043c\u0438 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0430\u043c\u0438.\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043e\u0431\u044a\u044f\u0432\u0438\u043b \u043e \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u043e\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u2028\u000d\u000a\u0431\u0430\u043d\u043a\u043e\u0432 \u0438 \u0437\u0430\u0435\u043c\u0449\u0438\u043a\u043e\u0432\u000d\u000a\u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u0435 \u043e\u0431\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435, \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u043f\u043e\u0434\u043e\u0448\u043b\u0430 \u043a \u043a\u0440\u0438\u0437\u0438\u0441\u0443 \u000d\u000a\u0432 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u043c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0438. \u0412 2025 \u0433\u043e\u0434\u0443 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u0412\u0412\u041f \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 3,5%.\u000d\u000a\u0426\u0435\u043d\u0442\u0440\u043e\u0431\u0430\u043d\u043a \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0430\u043d\u043e\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043b \u043f\u0430\u043a\u0435\u0442 \u043c\u0435\u0440 \u000d\u000a\u0434\u043b\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438 \u0438 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u0441\u0435\u043a\u0442\u043e\u0440\u0430 \u043d\u0430 \u0444\u043e\u043d\u0435 \u0431\u043b\u0438\u0436\u043d\u0435\u0432\u043e\u0441\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430. \u0420\u043e\u0437\u043d\u0438\u0447\u043d\u044b\u0435 \u0431\u0430\u043d\u043a\u0438 \u0438 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0442 \u0444\u0438\u0437\u043b\u0438\u0446\u0430\u043c \u0438 \u0431\u0438\u0437\u043d\u0435\u0441\u0443 \u000d\u000a\u043e\u0442\u043b\u043e\u0436\u0438\u0442\u044c \u0432\u044b\u043f\u043b\u0430\u0442\u044b \u043f\u043e \u043a\u0440\u0435\u0434\u0438\u0442\u0430\u043c \u0438 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u044b\u043c \u000d\u000a\u043a\u0430\u0440\u0442\u0430\u043c \u043d\u0430 \u0442\u0440\u0438 \u043c\u0435\u0441\u044f\u0446\u0430. \u000a\u000d\u000a\u041e\u0442\u0441\u0440\u043e\u0447\u043a\u0430 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u044f\u0442\u044c\u0441\u044f \u043a\u0430\u043a \u000d\u000a\u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u043d\u0443\u044e \u0441\u0443\u043c\u043c\u0443 \u0434\u043e\u043b\u0433\u0430, \u0442\u0430\u043a \u0438 \u043d\u0430 \u043f\u0440\u043e\u0446\u0435\u043d\u0442\u044b. \u000d\u000a\u0411\u0430\u043d\u043a\u0430\u043c \u0442\u0430\u043a\u0436\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0442 \u0431\u043e\u043b\u0435\u0435 \u0433\u0438\u0431\u043a\u043e \u000d\u000a\u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442\u044c \u043a \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u043d\u044b\u0445 \u000d\u000a\u043a\u0440\u0435\u0434\u0438\u0442\u043e\u0432. \u041e\u0431\u0449\u0438\u0439 \u043e\u0431\u044a\u0435\u043c \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043e\u0432 \u000d\u000a\u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u2028\u000d\u000a\u0432 $30,05 \u043c\u043b\u0440\u0434.\u000d\u000a\u0414\u043b\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u0439 \u000d\u000a\u0441\u0438\u0441\u0442\u0435\u043c\u044b \u0426\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0439 \u0431\u0430\u043d\u043a \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u000d\u000a\u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u0440\u043e\u0437\u043d\u0438\u0447\u043d\u044b\u043c \u0431\u0430\u043d\u043a\u0430\u043c \u000d\u000a\u043d\u0435\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u043e\u0435 \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u000d\u000a\u043f\u043e\u0434 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u043d\u044b\u0439 \u0437\u0430\u043b\u043e\u0433 \u043d\u0430 \u0441\u0440\u043e\u043a \u0434\u043e \u0448\u0435\u0441\u0442\u0438 \u000d\u000a\u043c\u0435\u0441\u044f\u0446\u0435\u0432. \u041e\u0431\u044a\u0435\u043c \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u000d\u000a\u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432 $18,6 \u043c\u043b\u0440\u0434. \u000a\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440 \u043f\u0440\u043e\u0434\u043b\u0438\u043b \u0441\u0440\u043e\u043a \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0439 \u000d\u000a\u0440\u0435\u043f\u043e \u0434\u043e \u0442\u0440\u0435\u0445 \u043c\u0435\u0441\u044f\u0446\u0435\u0432, \u0441\u043d\u0438\u0437\u0438\u043b \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u000d\u000a\u0440\u0435\u0437\u0435\u0440\u0432\u044b \u0434\u043b\u044f \u0431\u0430\u043d\u043a\u043e\u0432 \u0441 5% \u0434\u043e 3,5%, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u043d\u043e\u0440\u043c\u0430\u0442\u0438\u0432\u044b \u000d\u000a\u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442\u0430 \u043f\u043e\u043a\u0440\u044b\u0442\u0438\u044f \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0438 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442\u0430 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0433\u043e \u0444\u043e\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u000d\u000a\u0441\u043e 100% \u0434\u043e 80%.\u000d\u000a09 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0412 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0437\u0430 \u0432\u0437\u044f\u0442\u043a\u0438 \u043e\u0442 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0430\u0440\u0435\u0441\u0442\u043e\u0432\u0430\u043d \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0440\u0435\u0432\u0438\u0437\u043e\u0440 \u0441\u0442\u0440\u0430\u043d\u044b\u000d\u000a\u0425\u0435\u0440\u0438 \u0421\u0443\u0441\u0430\u043d\u0442\u043e \u0443\u0441\u043f\u0435\u043b \u043f\u0440\u043e\u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0432 \u043d\u043e\u0432\u043e\u0439 \u0434\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u0438 \u0432\u0441\u0435\u0433\u043e \u0448\u0435\u0441\u0442\u044c \u0434\u043d\u0435\u0439. \u0415\u043c\u0443 \u0432\u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u000d\u000a\u0437\u043b\u043e\u0443\u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u044f \u043d\u0430 \u0431\u043e\u043b\u0435\u0435 \u043d\u0438\u0437\u043a\u043e\u0439 \u043f\u043e\u0437\u0438\u0446\u0438\u0438.\u000d\u000a\u0413\u0435\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u0440\u043e\u043a\u0443\u0440\u0430\u0442\u0443\u0440\u0430 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u000d\u000a\u043f\u0440\u0435\u0434\u044a\u044f\u0432\u0438\u043b\u0430 \u0433\u043b\u0430\u0432\u0435 \u041d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u043a\u043e\u043c\u0438\u0441\u0441\u0438\u0438 \u000d\u000a\u043f\u043e \u043f\u0440\u0430\u0432\u0430\u043c \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430 \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u043e\u0431\u0432\u0438\u043d\u0435\u043d\u0438\u0435 \u000d\u000a\u0432 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u0438 \u0432\u0437\u044f\u0442\u043a\u0438 \u043e\u0442 \u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438, \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0438 \u0432 \u0447\u0435\u0442\u0432\u0435\u0440\u0433 \u0432\u043b\u0430\u0441\u0442\u0438. \u0421\u0440\u0430\u0437\u0443 \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0433\u043e \u0447\u0438\u043d\u043e\u0432\u043d\u0438\u043a \u0431\u044b\u043b \u0437\u0430\u0434\u0435\u0440\u0436\u0430\u043d \u000d\u000a\u043d\u0430 20 \u0441\u0443\u0442\u043e\u043a.\u000a\u000d\u000a\u041f\u043e \u0432\u0435\u0440\u0441\u0438\u0438 \u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f, \u043d\u0430\u0445\u043e\u0434\u044f\u0441\u044c \u043d\u0430 \u0434\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u043a\u043e\u043c\u0438\u0441\u0441\u0430\u0440\u0430 \u0442\u043e\u0433\u043e \u0436\u0435 \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u0430 \u0441 2021 \u2028\u000d\u000a\u043f\u043e 2026 \u0433\u043e\u0434\u044b, \u0425\u0435\u0440\u0438 \u0421\u0443\u0441\u0430\u043d\u0442\u043e \u043f\u043e\u043b\u0443\u0447\u0438\u043b \u000d\u000a\u043e\u0442 \u0447\u0430\u0441\u0442\u043d\u043e\u0439 \u0444\u0438\u0440\u043c\u044b PT Toshida Indonesia \u000d\u000a\u043f\u043e\u0440\u044f\u0434\u043a\u0430 $90 \u0442\u044b\u0441. \u0412\u0437\u0430\u043c\u0435\u043d \u043e\u043d \u043f\u043e\u043c\u043e\u0433\u0430\u043b \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438, \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043d\u0430 \u0421\u0443\u043b\u0430\u0432\u0435\u0441\u0438,\u000d\u000a\u0437\u0430\u043d\u0438\u0436\u0430\u0442\u044c \u0441\u0443\u043c\u043c\u044b \u043d\u0435\u043d\u0430\u043b\u043e\u0433\u043e\u0432\u044b\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u0434\u043e\u0445\u043e\u0434\u043e\u0432 (PNBP). \u042d\u0442\u043e \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u0431\u043e\u0440, \u000d\u000a\u043d\u0430\u0447\u0438\u0441\u043b\u044f\u0435\u043c\u044b\u0439 \u043c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e\u043c \u0441\u0435\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0445\u043e\u0437\u044f\u0439\u0441\u0442\u0432\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0434\u043e\u043b\u0436\u043d\u0430 \u0431\u044b\u043b\u0430 \u000d\u000a\u0443\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u0437\u0430 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0433\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u000d\u000a\u0432 \u043b\u0435\u0441\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u0438 \u043e\u0441\u0442\u0440\u043e\u0432\u0430. \u000a\u000d\u000aPT Toshida Indonesia \u043f\u043e\u043f\u0430\u043b\u0430 \u0432 \u043f\u043e\u043b\u0435 \u0437\u0440\u0435\u043d\u0438\u044f \u000d\u000a\u043f\u0440\u0430\u0432\u043e\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u0435\u0439 \u0435\u0449\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043b\u0435\u0442 \u043d\u0430\u0437\u0430\u0434. \u000d\u000a\u041d\u043e \u043e\u0431\u0432\u0438\u043d\u0435\u043d\u0438\u044f \u0432 \u0430\u0434\u0440\u0435\u0441 \u0425\u0435\u0440\u0438 \u0421\u0443\u0441\u0430\u043d\u0442\u043e \u0431\u044b\u043b\u0438 \u000d\u000a\u0432\u044b\u0434\u0432\u0438\u043d\u0443\u0442\u044b \u043b\u0438\u0448\u044c \u043f\u043e\u0441\u043b\u0435 \u0442\u043e\u0433\u043e, \u043a\u0430\u043a \u0443 \u043f\u0440\u043e\u043a\u0443\u0440\u0430\u0442\u0443\u0440\u044b \u000d\u000a\u043f\u043e\u044f\u0432\u0438\u043b\u0438\u0441\u044c \u043f\u0440\u043e\u0447\u043d\u044b\u0435 \u0434\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0435\u0433\u043e \u0432\u0438\u043d\u044b. \u000d\u000a\u0422\u0435\u043f\u0435\u0440\u044c \u0447\u0438\u043d\u043e\u0432\u043d\u0438\u043a\u0443 \u0433\u0440\u043e\u0437\u0438\u0442 \u0434\u043e \u0442\u0440\u0435\u0445 \u043b\u0435\u0442 \u043b\u0438\u0448\u0435\u043d\u0438\u044f \u000d\u000a\u0441\u0432\u043e\u0431\u043e\u0434\u044b.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0444\u0438\u043d\u0430\u043d\u0441\u044b\u000d\u000a\u0428\u0430\u043d\u0445\u0430\u0439\u0441\u043a\u0430\u044f \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u043d\u0430\u044f \u0431\u0438\u0440\u0436\u0430 \u043e\u0442\u043a\u0440\u044b\u043b\u0430 \u000d\u000a\u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u0446\u0430\u043c \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430\u043c\u000d\u000a\u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0446\u0435\u043d\u0443 \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u044c \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u043e\u0442 \u041b\u043e\u043d\u0434\u043e\u043d\u0441\u043a\u043e\u0439 \u0431\u0438\u0440\u0436\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432, \u0447\u0442\u043e \u000d\u000a\u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u043e \u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0435\u0439 \u0441\u0442\u0430\u043b\u0438 \u0438 \u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439.\u000d\u000a\u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e SHFE \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u043b\u043e \u0446\u0438\u0440\u043a\u0443\u043b\u044f\u0440 \u000d\u000a\u043e\u0431 \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u0438 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u043c \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430\u043c \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u000d\u000a\u043a \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u0430\u043c \u0438 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043c \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u044c \u000d\u000a\u0441 22 \u0430\u043f\u0440\u0435\u043b\u044f (\u043d\u0430\u0447\u0438\u043d\u0430\u044f \u0441 \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0439 \u000d\u000a\u0441\u0435\u0441\u0441\u0438\u0438 \u0432\u0435\u0447\u0435\u0440\u043e\u043c 21 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430). \u042d\u0442\u043e \u000d\u000a\u0441\u0442\u0430\u043b\u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u043c \u043f\u043e\u0441\u043b\u0435 \u0442\u043e\u0433\u043e, \u043a\u0430\u043a \u041a\u043e\u043c\u0438\u0441\u0441\u0438\u044f \u000d\u000a\u043f\u043e \u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u0446\u0435\u043d\u043d\u044b\u0445 \u0431\u0443\u043c\u0430\u0433 \u041a\u0438\u0442\u0430\u044f (CSRC) \u000d\u000a\u0432 \u044f\u043d\u0432\u0430\u0440\u0435 2026 \u0433\u043e\u0434\u0430 \u0434\u0430\u043b\u0430 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0435 \u000d\u000a\u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435.\u000a\u000d\u000a\u0418\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0435 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u0440\u044b\u043d\u043a\u0430 \u0441\u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u0440\u0430\u0441\u043f\u043b\u0430\u0447\u0438\u0432\u0430\u0442\u044c\u0441\u044f \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u043e\u0439 \u000d\u000a\u043f\u043e \u043a\u0443\u0440\u0441\u0443 95% \u043e\u0442 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u043e\u0439 \u000d\u000a\u0432\u0430\u043b\u044e\u0442\u043e\u0439 (CFETS). \u041d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0435 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b SHFE \u000d\u000a\u043e\u0434\u043d\u0438 \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u043b\u0438\u043a\u0432\u0438\u0434\u043d\u044b\u0445 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u0432 \u000d\u000a\u043d\u0430 \u0446\u0432\u0435\u0442\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u0432 \u043c\u0438\u0440\u0435 (200\u2013400 \u0442\u044b\u0441. \u043b\u043e\u0442\u043e\u0432 \u000d\u000a\u0432 \u0434\u0435\u043d\u044c), \u0438 \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u0435 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u0443\u043a\u0440\u0435\u043f\u0438\u0442 \u0432\u043b\u0438\u044f\u043d\u0438\u0435 \u000d\u000a\u041a\u0438\u0442\u0430\u044f \u043d\u0430 \u0446\u0435\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435, \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u000d\u000a\u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u044e \u041b\u043e\u043d\u0434\u043e\u043d\u0441\u043a\u043e\u0439 \u0431\u0438\u0440\u0436\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u000d\u000a(LME).\u000a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u044b\u0435 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u0431\u0440\u043e\u043a\u0435\u0440\u044b \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0438 \u000d\u000a\u0434\u043e\u0441\u0442\u0443\u043f \u0434\u043b\u044f \u0441\u0432\u043e\u0438\u0445 \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432 \u0441 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0434\u043d\u044f \u000d\u000a\u0442\u043e\u0440\u0433\u043e\u0432.\u000d\u000a10 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aCATL \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u043b\u0438\u043d\u0435\u0439\u043a\u0443 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u000d\u000a\u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439 \u0440\u0430\u0437\u043d\u043e\u0433\u043e \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0432 \u043c\u0438\u0440\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0442\u044f\u0433\u043e\u0432\u044b\u0445 \u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u043f\u0440\u043e\u0432\u0435\u043b \u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0446\u0438\u044e \u0437\u0430 \u0434\u0435\u043d\u044c \u000d\u000a\u0434\u043e \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u044f \u041f\u0435\u043a\u0438\u043d\u0441\u043a\u043e\u0433\u043e \u0430\u0432\u0442\u043e\u0441\u0430\u043b\u043e\u043d\u0430, \u0447\u0442\u043e\u0431\u044b \u043e\u043f\u0435\u0440\u0435\u0434\u0438\u0442\u044c \u0433\u043b\u0430\u0432\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u0430 \u2014 BYD.\u000d\u000a21 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430 Contemporary Amperex \u000d\u000aTechnology Co. Ltd \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u000d\u000a\u0441\u0432\u043e\u0435 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0434\u043b\u044f \u043b\u0438\u043d\u0435\u0439\u043a\u0438 \u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u043d\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f \u2014 \u0438\u0437 \u043f\u044f\u0442\u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0439. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0434\u043e\u0431\u0438\u0442\u044c\u0441\u044f \u0432\u044b\u0441\u043e\u043a\u043e\u0439 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u0438 \u0437\u0430\u0440\u044f\u0434\u043a\u0438 \u000d\u000a\u0434\u043b\u044f \u043b\u0438\u0442\u0438\u0439-\u0436\u0435\u043b\u0435\u0437\u043e-\u0444\u043e\u0441\u0444\u0430\u0442\u043d\u043e\u0439 \u0431\u0430\u0442\u0430\u0440\u0435\u0438 \u000d\u000aShenxing \u0442\u0440\u0435\u0442\u044c\u0435\u0433\u043e \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f \u2014 \u0448\u0435\u0441\u0442\u044c \u043c\u0438\u043d\u0443\u0442 \u000d\u000a\u043f\u0440\u0438 \u043a\u043e\u043c\u043d\u0430\u0442\u043d\u043e\u0439 \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0435 \u0438 \u0434\u0435\u0432\u044f\u0442\u044c \u043c\u0438\u043d\u0443\u0442 \u000d\u000a\u043f\u0440\u0438 \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0435 \u221230\u00b0 C. \u042d\u0442\u043e \u043d\u0430 \u0442\u0440\u0435\u0442\u044c \u0431\u044b\u0441\u0442\u0440\u0435\u0435, \u000d\u000a\u0447\u0435\u043c \u0443 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043e\u0432, \u0438 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0430\u0435\u0442 \u000d\u000a\u0432\u0440\u0435\u043c\u044f \u0437\u0430\u0440\u044f\u0434\u043a\u0438 \u043a \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0437\u0430\u043f\u0440\u0430\u0432\u043a\u0438 \u000d\u000a\u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u044f \u0431\u0435\u043d\u0437\u0438\u043d\u043e\u043c. \u041c\u043e\u0434\u0435\u043b\u0438 Qilin III \u0438 Qilin \u000d\u000aCondensed \u0438\u043c\u0435\u044e\u0442 \u0437\u0430\u043f\u0430\u0441 \u0445\u043e\u0434\u0430 1500 \u043a\u043c, \u0447\u0442\u043e, \u000d\u000a\u043f\u043e \u043c\u043d\u0435\u043d\u0438\u044e \u044d\u043a\u0441\u043f\u0435\u0440\u0442\u043e\u0432, \u043f\u043e\u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u043c \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u043c \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u0442\u044c \u000d\u000a\u043f\u0441\u0438\u0445\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0431\u0430\u0440\u044c\u0435\u0440 \u00ab1000 \u043c\u0438\u043b\u044c\u00bb \u2014 \u000d\u000a\u0441 \u0442\u0430\u043a\u0438\u043c \u0437\u0430\u043f\u0430\u0441\u043e\u043c \u0445\u043e\u0434\u0430 \u043c\u043e\u0436\u043d\u043e \u043d\u0435 \u0431\u043e\u044f\u0442\u044c\u0441\u044f \u043d\u0435 \u000d\u000a\u0434\u043e\u0435\u0445\u0430\u0442\u044c \u0434\u043e \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u0439 \u0437\u0430\u0440\u044f\u0434\u043d\u043e\u0439 \u0441\u0442\u0430\u043d\u0446\u0438\u0438. \u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c Qilin Condensed \u043f\u043e\u0437\u0438\u0446\u0438\u043e\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u000d\u000a\u043a\u0430\u043a \u0431\u043e\u043b\u0435\u0435 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u044b\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0438\u0439 \u000d\u000a\u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e\u0441\u0442\u044c \u0443\u0442\u0435\u0447\u0435\u043a \u0438 \u0432\u043e\u0437\u0433\u043e\u0440\u0430\u043d\u0438\u044f. \u041c\u043e\u0434\u0435\u043b\u044c \u000d\u000aFreevoy II \u0441\u043e\u0437\u0434\u0430\u043d\u0430 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u0434\u043b\u044f \u0433\u0438\u0431\u0440\u0438\u0434\u043e\u0432, \u000d\u000a\u043e\u043d\u0430 \u0434\u0430\u0435\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0435\u0445\u0430\u0442\u044c \u0434\u043e 600 \u043a\u043c \u000d\u000a\u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u044d\u043b\u0435\u043a\u0442\u0440\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u0438 \u0434\u043e 2000 \u043a\u043c \u000d\u000a\u0432 \u0441\u043c\u0435\u0448\u0430\u043d\u043d\u043e\u043c \u0446\u0438\u043a\u043b\u0435.\u000a\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, CATL \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430, \u0447\u0442\u043e \u043a \u043a\u043e\u043d\u0446\u0443 \u000d\u000a2026 \u0433\u043e\u0434\u0430 \u043f\u0435\u0440\u0432\u043e\u0439 \u0432 \u043c\u0438\u0440\u0435 \u043d\u0430\u0447\u043d\u0435\u0442 \u043c\u0430\u0441\u0441\u043e\u0432\u043e\u0435 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u0430\u0442\u0440\u0438\u0439\u0438\u043e\u043d\u043d\u044b\u0445 \u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u0441\u0435\u0440\u0438\u0438 \u000d\u000aNaxtra. \u041f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u0441\u0438\u043b\u043e\u0432\u044b\u0445 \u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u0441 \u0442\u0430\u043a\u0438\u043c \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u043e\u043c \u0437\u0430\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0432 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u043d\u043e\u043c \u000d\u000a\u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435 \u0440\u0430\u0431\u043e\u0447\u0438\u0445 \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440, \u043c\u0435\u043d\u044c\u0448\u0435\u043c \u0440\u0438\u0441\u043a\u0435 \u000d\u000a\u0432\u043e\u0437\u0433\u043e\u0440\u0430\u043d\u0438\u044f, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0432 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 \u043d\u0430\u0442\u0440\u0438\u044f.  \u000a\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u043d\u0430\u0443\u0447\u043d\u044b\u0439 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a CATL \u0423 \u041a\u0430\u0439 \u0437\u0430\u044f\u0432\u0438\u043b, \u000d\u000a\u0447\u0442\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u043d\u044b\u0445 \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0432 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442\u044c \u000d\u000a\u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0430 \u000d\u000a\u0440\u044b\u043d\u043a\u0430, \u043e\u0442 \u0431\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0445 \u0433\u043e\u0440\u043e\u0434\u0441\u043a\u0438\u0445 \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439 \u000d\u000a\u0434\u043e \u043c\u0430\u0448\u0438\u043d \u043a\u043b\u0430\u0441\u0441\u0430 \u043b\u044e\u043a\u0441 \u0438 \u0442\u044f\u0436\u0435\u043b\u044b\u0445 \u0433\u0440\u0443\u0437\u043e\u0432\u0438\u043a\u043e\u0432. \u000d\u000a\u041f\u043e\u043c\u0438\u043c\u043e \u0442\u043e\u0433\u043e, \u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0434\u0438\u0432\u0435\u0440\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u000d\u000a\u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0441\u043e\u0441\u0442\u0430\u0432\u0430 \u043f\u043e\u043c\u043e\u0436\u0435\u0442 CATL \u000d\u000a\u0437\u0430\u0441\u0442\u0440\u0430\u0445\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u043e\u0442 \u0440\u0435\u0437\u043a\u0438\u0445 \u043a\u043e\u043b\u0435\u0431\u0430\u043d\u0438\u0439 \u0446\u0435\u043d \u000d\u000a\u043d\u0430 \u043b\u0438\u0442\u0438\u0439, \u043d\u0438\u043a\u0435\u043b\u044c \u0438 \u043a\u043e\u0431\u0430\u043b\u044c\u0442.\u000d\u000a11 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0413\u043e\u0441\u0441\u0442\u0430\u0442 \u041a\u041d\u0420 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043b \u0434\u0430\u043d\u043d\u044b\u0435 \u043e \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u043e\u043c \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435 \u043c\u0435\u0434\u0438 \u0432 \u043c\u0430\u0440\u0442\u0435\u000d\u000a\u0412 \u0430\u043f\u0440\u0435\u043b\u0435 \u043c\u043d\u043e\u0433\u0438\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0443\u0436\u0435 \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0438, \u0447\u0442\u043e \u0441\u043e\u043a\u0440\u0430\u0442\u044f\u0442 \u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0443 \u0438 \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u044f\u0442 \u000d\u000a\u0437\u0430\u0432\u043e\u0434\u044b \u043d\u0430 \u0442\u0435\u0445\u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u0435. \u0418 \u0440\u043e\u0441\u0442, \u0438 \u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0441\u0432\u044f\u0437\u0430\u043d\u044b \u0441 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u043e\u043c \u0441\u0435\u0440\u044b \u0438\u0437-\u0437\u0430 \u000d\u000a\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430.\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0413\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f, \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u043c 21 \u0430\u043f\u0440\u0435\u043b\u044f, \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u0432 \u041a\u0438\u0442\u0430\u0435 \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u043e \u0432 \u043c\u0430\u0440\u0442\u0435 1,33 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u0447\u0442\u043e \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u000d\u000a\u0441\u0430\u043c\u044b\u043c \u0432\u044b\u0441\u043e\u043a\u0438\u043c \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0435\u043c \u0437\u0430 \u0432\u0441\u044e \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u000d\u000a\u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0439 \u0441 1990 \u0433\u043e\u0434\u0430.\u000a\u000d\u000a\u041a\u0430\u043a \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442 Bloomberg, \u0432\u0430\u0436\u043d\u044b\u043c \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u043c \u000d\u000a\u0440\u043e\u0441\u0442\u0430 \u0441\u0442\u0430\u043b\u043e \u0440\u0435\u0437\u043a\u043e\u0435 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u0435 \u0434\u043e\u0445\u043e\u0434\u043e\u0432 \u043e\u0442 \u000d\u000a\u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b, \u0446\u0435\u043d\u044b \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0432 \u041a\u0438\u0442\u0430\u0435 \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0438 \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u043e\u0433\u043e \u0443\u0440\u043e\u0432\u043d\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u0441\u0435\u0440\u044b \u0438\u0437-\u0437\u0430 \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0442\u0438\u044f \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432\u0430. \u041d\u0430 \u043a\u0430\u0436\u0434\u0443\u044e \u0442\u043e\u043d\u043d\u0443 \u043c\u0435\u0434\u0438 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u000d\u000a\u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0432\u043e\u0434\u044b \u043c\u043e\u0433\u0443\u0442 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0431\u043e\u043b\u0435\u0435 \u000d\u000a5 \u0442\u044b\u0441. \u044e\u0430\u043d\u0435\u0439 ($733) \u043d\u0430 \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u0435, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u0430\u044f \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u043c \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u043e\u043c \u000d\u000a\u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0438. \u042d\u0442\u043e \u0441\u0442\u0438\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043b\u043e \u0437\u0430\u0432\u043e\u0434\u044b \u000d\u000a\u043a \u043d\u0430\u0440\u0430\u0449\u0438\u0432\u0430\u043d\u0438\u044e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430, \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u000d\u000a\u043d\u0430 \u043d\u0438\u0437\u043a\u0438\u0435 \u0440\u0430\u0441\u0446\u0435\u043d\u043a\u0438 \u043d\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0443 \u000d\u000a\u043c\u0435\u0434\u0438 \u0438 \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0440\u0443\u0434\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0430. \u0420\u0435\u0448\u0438\u0442\u044c \u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0434\u043d\u044e\u044e \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0443 \u043f\u043e\u043c\u043e\u0433\u043b\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u000d\u000a\u043c\u0435\u0434\u043d\u043e\u0433\u043e \u043b\u043e\u043c\u0430.\u000a\u000d\u000a\u041c\u0430\u0440\u0442\u043e\u0432\u0441\u043a\u0438\u0439 \u0440\u0435\u043a\u043e\u0440\u0434, \u043f\u043e\u0445\u043e\u0436\u0435, \u043d\u0430\u0434\u043e\u043b\u0433\u043e \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u000d\u000a\u043d\u0435\u043f\u043e\u0431\u0438\u0442\u044b\u043c. \u0423\u0436\u0435 \u0432 \u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0435 \u0430\u043f\u0440\u0435\u043b\u044f \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u000d\u000a\u0441\u0435\u0440\u044b \u0438 \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b \u043f\u0435\u0440\u0435\u0448\u0435\u043b \u0432 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0443\u044e \u000d\u000a\u0444\u0430\u0437\u0443 \u2014 \u0432\u043b\u0430\u0441\u0442\u0438 \u041a\u041d\u0420 \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u043b\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0441\u0435\u0440\u043d\u043e\u0439 \u000d\u000a\u043a\u0438\u0441\u043b\u043e\u0442\u044b, \u0442\u0430\u043a \u043a\u0430\u043a \u043e\u043d\u0430 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0434\u043b\u044f \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0443\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0439, \u0432\u043d\u043e\u0441\u0438\u0442\u044c \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u0432\u0435\u0441\u043d\u043e\u0439 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0441\u0435\u043b\u044c\u0441\u043a\u043e\u0445\u043e\u0437\u044f\u0439\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u000d\u000a\u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u044c. \u041f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0433\u043e \u0440\u044f\u0434 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u043b \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u0441\u043d\u0438\u0437\u0438\u0442\u044c \u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0443 \u043c\u0435\u0434\u0438 \u000d\u000a\u0438 \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e \u043f\u0440\u0435\u0440\u0432\u0430\u0442\u044c\u0441\u044f \u043d\u0430 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u000d\u000a\u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u0435.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aFreeport Indonesia \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442 \u043e\u0431\u044a\u0435\u043c\u044b \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u043a\u0430\u0442\u043e\u0434\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u0434\u043e \u043a\u043e\u043d\u0446\u0430 \u0433\u043e\u0434\u0430 \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u0442 \u0432 2026 \u0433\u043e\u0434\u0443 1,1 \u043c\u043b\u0440\u0434 \u0444\u0443\u043d\u0442\u043e\u0432 \u043a\u0430\u0442\u043e\u0434\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u0438 0,8 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439 \u0437\u043e\u043b\u043e\u0442\u0430. \u000d\u000a\u042d\u0442\u043e \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e\u0434\u043d\u0435\u0433\u043e \u043e\u043f\u043e\u043b\u0437\u043d\u044f, \u000d\u000a\u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u043f\u043e\u0433\u0438\u0431\u043b\u0438 \u0441\u0435\u043c\u044c \u000d\u000a\u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u043e\u0432.\u000a\u000d\u000a\u0413\u0435\u043d\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 Freeport Indonesia \u0422\u043e\u043d\u0438 \u0412\u0435\u043d\u0430\u0441 \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b \u0432 \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a, 13 \u043c\u0430\u0440\u0442\u0430, \u0447\u0442\u043e \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0441\u0442\u0438 \u0432 \u044d\u0442\u043e\u043c \u0433\u043e\u0434\u0443 1,1 \u043c\u043b\u0440\u0434 \u000d\u000a\u0444\u0443\u043d\u0442\u043e\u0432 \u043a\u0430\u0442\u043e\u0434\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u0438 \u043e\u043a\u043e\u043b\u043e 0,8 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 Reuters. \u041f\u0440\u043e\u0433\u043d\u043e\u0437 \u000d\u000a\u043d\u0430 2027 \u0433\u043e\u0434 \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 1,5 \u043c\u043b\u0440\u0434 \u0444\u0443\u043d\u0442\u043e\u0432 \u043c\u0435\u0434\u0438 \u000d\u000a\u0438 1,3 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439 \u0437\u043e\u043b\u043e\u0442\u0430.\u000d\u000a12 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0438 \u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u0432\u044b\u0432\u0435\u0441\u0442\u0438 \u000d\u000a\u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0441\u0442\u0432\u043e \u043d\u0430 \u043d\u043e\u0432\u044b\u0439 \u0443\u0440\u043e\u0432\u0435\u043d\u044c\u000d\u000a\u042d\u0442\u043e \u0434\u043e\u043b\u0436\u043d\u043e \u043e\u0431\u043b\u0435\u0433\u0447\u0438\u0442\u044c \u041f\u0435\u043a\u0438\u043d\u0443 \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u043c \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u043c \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u044b \u0438 \u0437\u0430\u0449\u0438\u0442\u0443 \u000d\u000a\u0431\u0438\u0437\u043d\u0435\u0441\u0430. \u041c\u0430\u043f\u0443\u0442\u0443 \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u043e\u0442 \u041a\u0438\u0442\u0430\u044f \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0438 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438.\u000d\u000a\u041f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u044c \u041a\u041d\u0420 \u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d \u0438 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u000d\u000a\u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a\u0430 \u0414\u0430\u043d\u0438\u044d\u043b \u0424\u0440\u0430\u043d\u0441\u0438\u0448\u043a\u0443 \u0428\u0430\u043f\u0443 \u000d\u000a\u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u043f\u043e\u0434\u043d\u044f\u0442\u044c \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0435 \u000d\u000a\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0434\u043e \u0443\u0440\u043e\u0432\u043d\u044f \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u043c\u043e\u0437\u0430\u043c\u0431\u0438\u043a\u0441\u043a\u043e\u0433\u043e \u00ab\u0441\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u0430 \u0435\u0434\u0438\u043d\u043e\u0439 \u0441\u0443\u0434\u044c\u0431\u044b \u000d\u000a\u0432 \u043d\u043e\u0432\u0443\u044e \u044d\u043f\u043e\u0445\u0443\u00bb. \u0412 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438 \u044d\u0442\u0430 \u000d\u000a\u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u0438\u043c\u0435\u0435\u0442 \u0431\u043e\u043b\u0435\u0435 \u0432\u044b\u0441\u043e\u043a\u0438\u0439 \u0441\u0442\u0430\u0442\u0443\u0441, \u0447\u0435\u043c \u000d\u000a\u0434\u0430\u0436\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0441\u0442\u0432\u0430. \u000d\u000a\u0413\u043b\u0430\u0432\u0430 \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u044b \u043f\u0440\u043e\u0431\u044b\u043b \u0432 \u041a\u0438\u0442\u0430\u0435 \u000d\u000a\u043f\u043e\u0447\u0442\u0438 \u043d\u0435\u0434\u0435\u043b\u044e, \u043f\u043e\u0441\u0435\u0442\u0438\u0432 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u041f\u0435\u043a\u0438\u043d, \u000d\u000a\u043d\u043e \u0438 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044e \u0426\u0438\u043d\u0445\u0430\u0439, \u0433\u0434\u0435 \u043e\u043d \u043f\u043e\u0437\u043d\u0430\u043a\u043e\u043c\u0438\u043b\u0441\u044f \u000d\u000a\u0441 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e\u043c \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u000d\u000aWestern Mining \u0438 Qinghai Copper Co.\u000a\u000d\u000a\u0412 \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0435 \u0441 \u043f\u0440\u0435\u043c\u044c\u0435\u0440\u043e\u043c \u0413\u043e\u0441\u0441\u043e\u0432\u0435\u0442\u0430 \u041a\u041d\u0420 \u041b\u0438 \u000d\u000a\u0426\u044f\u043d\u043e\u043c \u0428\u0430\u043f\u0443 \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u043d\u0443\u043b, \u0447\u0442\u043e \u0435\u0433\u043e \u0441\u0442\u0440\u0430\u043d\u0430 \u000d\u000a\u0433\u043e\u0442\u043e\u0432\u0430 \u0443\u0433\u043b\u0443\u0431\u043b\u044f\u0442\u044c \u043a\u043e\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u044e \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u000d\u000a\u0438\u043d\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u044b \u00ab\u041f\u043e\u044f\u0441 \u0438 \u043f\u0443\u0442\u044c\u00bb \u0432 \u0442\u0430\u043a\u0438\u0445 \u043e\u0431\u043b\u0430\u0441\u0442\u044f\u0445, \u000d\u000a\u043a\u0430\u043a \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f, \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438, \u0441\u0435\u043b\u044c\u0441\u043a\u043e\u0435 \u0445\u043e\u0437\u044f\u0439\u0441\u0442\u0432\u043e, \u000d\u000a\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0430, \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442 \u0438 \u0441\u0432\u044f\u0437\u044c. \u000d\u000a\u0423\u043a\u0430\u0437\u0430\u0432, \u0447\u0442\u043e \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442 \u000d\u000a\u0441\u0438\u043b\u044c\u043d\u044b\u0435 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0432 \u000d\u000a\u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u0435\u043d\u0438\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0432 \u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a, \u041b\u0438 \u0426\u044f\u043d \u000d\u000a\u0432\u044b\u0440\u0430\u0437\u0438\u043b \u043d\u0430\u0434\u0435\u0436\u0434\u0443, \u0447\u0442\u043e \u043c\u043e\u0437\u0430\u043c\u0431\u0438\u043a\u0441\u043a\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u000d\u000a\u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0443\u044e \u0438 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0443\u0435\u043c\u0443\u044e \u000d\u000a\u0434\u0435\u043b\u043e\u0432\u0443\u044e \u0441\u0440\u0435\u0434\u0443, \u0437\u0430\u0449\u0438\u0442\u0438\u0442 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c, \u043f\u0440\u0430\u0432\u0430 \u000d\u000a\u0438 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u044b \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439. \u041e\u043d \u043f\u0440\u0438\u0437\u0432\u0430\u043b \u000d\u000a\u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u0442\u0435\u043c, \u0447\u0442\u043e \u041a\u0438\u0442\u0430\u0439 \u0432\u0432\u043e\u0434\u0438\u0442 \u000d\u000a\u0434\u043b\u044f \u0441\u0442\u0440\u0430\u043d\u044b \u043d\u0443\u043b\u0435\u0432\u044b\u0435 \u0442\u0430\u043c\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u043f\u043e\u0448\u043b\u0438\u043d\u044b \u000d\u000a\u043d\u0430 \u0432\u0441\u0435 \u0442\u043e\u0432\u0430\u0440\u044b. \u000a\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0437\u0430\u0438\u043d\u0442\u0435\u0440\u0435\u0441\u043e\u0432\u0430\u043d \u0432 \u043c\u043e\u0437\u0430\u043c\u0431\u0438\u043a\u0441\u043a\u0438\u0445 \u000d\u000a\u043f\u0440\u0438\u0440\u043e\u0434\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u0445, \u0442\u0430\u043a\u0438\u0445 \u043a\u0430\u043a \u0433\u0440\u0430\u0444\u0438\u0442, \u043b\u0438\u0442\u0438\u0439, \u000d\u000a\u0442\u0438\u0442\u0430\u043d, \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b. \u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0433\u043e\u0442\u043e\u0432\u044b \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0432 \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u000d\u000a\u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u043e\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0434\u043b\u044f \u000d\u000a\u0432\u044b\u0432\u043e\u0437\u0430 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438. \u0427\u0442\u043e \u0436\u0435 \u043a\u0430\u0441\u0430\u0435\u0442\u0441\u044f \u0432\u043b\u0430\u0441\u0442\u0435\u0439 \u000d\u000a\u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a\u0430, \u0442\u043e \u043e\u043d\u0438 \u043d\u0430\u0434\u0435\u044e\u0442\u0441\u044f \u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e \u000d\u000a\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439 \u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0435\u0439 \u0430\u043a\u0442\u0438\u0432\u043d\u0435\u0435 \u000d\u000a\u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0442\u044c \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0443\u044e \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c.\u000d\u000a13 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u0432\u0432\u043e\u0434\u0438\u0442 \u043d\u043e\u0432\u0443\u044e \u0444\u043e\u0440\u043c\u0443\u043b\u0443 \u0440\u0430\u0441\u0447\u0435\u0442\u0430 \u2028\u000d\u000a\u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u0446\u0435\u043d\u044b \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u0443\u044e \u0440\u0443\u0434\u0443\u000d\u000a\u041f\u043e\u0434\u043e\u0440\u043e\u0436\u0430\u044e\u0442 \u0432\u0441\u0435 \u0441\u043e\u0440\u0442\u0430 \u0440\u0443\u0434\u044b, \u0447\u0442\u043e \u0431\u043e\u043b\u044c\u043d\u043e \u0443\u0434\u0430\u0440\u0438\u0442 \u043f\u043e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0441\u0442\u0440\u0430\u043d\u044b \u043f\u0440\u0438\u043d\u044f\u043b\u043e \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u000d\u000a\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0432 \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a, \u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043d\u043e\u0432\u0430\u044f \u000d\u000a\u043c\u0435\u0442\u043e\u0434\u0438\u043a\u0430 \u0440\u0430\u0441\u0447\u0435\u0442\u0430 \u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u0446\u0435\u043d\u044b \u043d\u0430 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0435 \u000d\u000a\u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0435 (HPM) \u0434\u043b\u044f \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u044b \u043d\u0430\u0447\u0430\u043b\u0430 \u000d\u000a\u0441\u043e \u0441\u0440\u0435\u0434\u044b, 15 \u0430\u043f\u0440\u0435\u043b\u044f.\u000a\u000d\u000a\u0411\u0430\u0437\u043e\u0432\u044b\u0435 \u0446\u0435\u043d\u044b \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u044e\u0442 \u000d\u000a\u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u0443\u044e \u0441\u0443\u043c\u043c\u0443, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u000d\u000a\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u0437\u0430\u0432\u043e\u0434 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c \u0437\u0430 \u0440\u0443\u0434\u0443. \u041e\u043d\u0438 \u000d\u000a\u0432\u0430\u0440\u044c\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u0446\u0435\u043d \u041b\u043e\u043d\u0434\u043e\u043d\u0441\u043a\u043e\u0439 \u000d\u000a\u0431\u0438\u0440\u0436\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 (LME) \u0438 \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u000d\u000a\u0434\u0432\u0430\u0436\u0434\u044b \u0432 \u043c\u0435\u0441\u044f\u0446. \u041e\u0434\u043d\u0430\u043a\u043e \u0442\u0435\u043f\u0435\u0440\u044c \u0432 \u0444\u043e\u0440\u043c\u0443\u043b\u0435 \u000d\u000a\u0431\u0443\u0434\u0435\u0442 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0442\u044c\u0441\u044f \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044f, \u043d\u043e \u0438 \u0441\u043e\u043f\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430, \u0445\u0440\u043e\u043c\u0430 \u000d\u000a\u0438 \u0436\u0435\u043b\u0435\u0437\u0430.\u000a\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u0430\u0439\u0442 Mysteel \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u043e \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f\u0445: \u000d\u000a\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u0434\u043b\u044f \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u000d\u000a\u0440\u0443\u0434\u044b \u0441 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435\u043c 1,6% \u043f\u043e\u0432\u044b\u0448\u0435\u043d \u0441 17% \u0434\u043e 30%, \u000d\u000a\u0430 \u043f\u0440\u0438 \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f \u043d\u0438\u043a\u0435\u043b\u044f \u043d\u0430 0,1% \u000d\u000a\u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u0431\u0443\u0434\u0435\u0442 \u0441\u043d\u0438\u0436\u0430\u0442\u044c\u0441\u044f \u0438\u043b\u0438 \u0440\u0430\u0441\u0442\u0438 \u043d\u0430 1%. \u000d\u000a\u0414\u043b\u044f \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0438 \u0436\u0435\u043b\u0435\u0437\u0430 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u000d\u000a\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 30%, \u0434\u043b\u044f \u0445\u0440\u043e\u043c\u0430 \u2014 10%. \u000d\u000a\u041a\u043e\u0431\u0430\u043b\u044c\u0442 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u043e\u0446\u0435\u043d\u043a\u0435 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u0436\u0435\u043b\u0435\u0437\u043e\u043c \u000d\u000a\u0438 \u0445\u0440\u043e\u043c\u043e\u043c \u043f\u0440\u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0438 \u0432\u044b\u0448\u0435 0,05%; \u000d\u000a\u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0439 \u0441 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u043e\u0439 \u043a\u043e\u0431\u0430\u043b\u044c\u0442 \u000d\u000a\u043e\u0431\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u043b\u043e\u0433\u043e\u043c \u043f\u043e \u0441\u0442\u0430\u0432\u043a\u0435 2%.\u000a\u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0430\u043b\u043e\u0433\u043e\u043e\u0431\u043b\u0430\u0433\u0430\u0435\u043c\u0430\u044f \u0431\u0430\u0437\u0430 \u0434\u043b\u044f \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u043e\u0441\u0442\u0430\u0435\u0442\u0441\u044f \u043d\u0435\u0438\u0437\u043c\u0435\u043d\u043d\u043e\u0439. \u041d\u043e\u0432\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u043f\u043e\u0432\u044b\u0441\u0438\u0442 \u000d\u000a\u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u0446\u0435\u043d\u044b \u043d\u0430 \u0432\u0441\u0435 \u0441\u043e\u0440\u0442\u0430 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u000d\u000a\u0440\u0443\u0434\u044b, \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442 Bloomberg. \u0420\u0430\u043d\u0435\u0435 \u0443\u0436\u0435\u0441\u0442\u043e\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u043a\u0432\u043e\u0442 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u0443\u0436\u0435 \u043f\u0440\u0438\u0432\u0435\u043b\u043e \u043a \u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u000d\u000a\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0432\u044b\u0441\u043e\u043a\u043e\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0440\u0443\u0434\u044b \u000d\u000a\u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b\u0430 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u000d\u000a\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u043d\u043e\u0440\u043c\u044b, \u0430 \u0442\u0435\u043f\u0435\u0440\u044c \u0432\u044b\u0440\u0430\u0441\u0442\u0443\u0442 \u0446\u0435\u043d\u044b \u000d\u000a\u0438 \u043d\u0430 \u043d\u0438\u0437\u043a\u043e\u0441\u043e\u0440\u0442\u043d\u0443\u044e \u0440\u0443\u0434\u0443. \u000a\u000d\u000a\u041a\u0430\u043a \u043f\u0440\u0430\u0432\u0438\u043b\u043e, \u0435\u0435 \u0437\u0430\u043a\u0443\u043f\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f, \u043f\u0440\u0435\u0436\u0434\u0435 \u000d\u000a\u0432\u0441\u0435\u0433\u043e \u0441 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u043e\u043c, \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u044e\u0449\u0438\u0435 \u000d\u000a\u043a\u0438\u0441\u043b\u043e\u0442\u043d\u043e\u0435 \u0432\u044b\u0449\u0435\u043b\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u0435 \u043f\u043e\u0434 \u0432\u044b\u0441\u043e\u043a\u0438\u043c \u000d\u000a\u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u043c (HPAL) \u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u043f\u043e\u043b\u0443\u043f\u0440\u043e\u0434\u0443\u043a\u0442\u043e\u0432, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0449\u0438\u0445\u0441\u044f \u000d\u000a\u043f\u0440\u0438 \u0438\u0437\u0433\u043e\u0442\u043e\u0432\u043b\u0435\u043d\u0438\u0438 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u000d\u000a\u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439. \u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0443\u0436\u0435 \u0438 \u0442\u0430\u043a \u000d\u000a\u0441\u0442\u0440\u0430\u0434\u0430\u044e\u0442 \u043e\u0442 \u0440\u0435\u0437\u043a\u043e\u0433\u043e \u0440\u043e\u0441\u0442\u0430 \u0446\u0435\u043d \u043d\u0430 \u0441\u0435\u0440\u0443, \u000d\u000a\u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u0432\u043e\u0439\u043d\u0430 \u0441 \u0418\u0440\u0430\u043d\u043e\u043c \u043d\u0435 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c \u0435\u0435 \u0438\u0437 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430.\u000d\u000a14 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043c\u043e\u0436\u0435\u0442 \u0443\u0436\u0435 \u0441 \u043c\u0430\u044f \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u0442\u044c \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u2028\u000d\u000a\u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b \u043d\u0430 \u0444\u043e\u043d\u0435 \u0438\u0440\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u043a\u0440\u0438\u0437\u0438\u0441\u0430\u000d\u000a\u041f\u0435\u0440\u0435\u043a\u0440\u044b\u0442\u0438\u0435 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u0446\u0435\u043f\u043d\u0443\u044e \u0440\u0435\u0430\u043a\u0446\u0438\u044e. \u041d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0435\u0444\u0442\u044c, \u000d\u000a\u043d\u043e \u0438 \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0435\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u2014 \u0441\u0435\u0440\u0430 \u2014 \u043e\u043a\u0430\u0437\u0430\u043b\u0438\u0441\u044c \u0432 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0435 \u043d\u0430 \u043c\u0438\u0440\u043e\u0432\u043e\u043c \u0440\u044b\u043d\u043a\u0435. \u000d\u000a\u041f\u0435\u0440\u0435\u0431\u043e\u0438 \u0441 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u043c\u0438 \u0441\u0435\u0440\u044b \u0438\u0437 \u0441\u0442\u0440\u0430\u043d \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u043f\u0440\u0438\u0432\u0435\u0434\u0443\u0442 \u043a \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043c\u0435\u0434\u0438 \u0432 \u041a\u0438\u0442\u0430\u0435 \u0438 \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438. \u041a\u0438\u0442\u0430\u0439 \u043c\u043e\u0436\u0435\u0442 \u0443\u0436\u0435 \u0441 \u043c\u0430\u044f \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u0442\u044c \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b \u043d\u0430 \u0444\u043e\u043d\u0435 \u0438\u0440\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043a\u0440\u0438\u0437\u0438\u0441\u0430, \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 Bloomberg. \u000a\u000d\u000a\u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b \u000d\u000a\u0432 \u0441\u0442\u0440\u0430\u043d\u0435 \u043d\u0435\u0434\u0430\u0432\u043d\u043e \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0443\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u044f \u000d\u000a\u043e \u0437\u0430\u043f\u0440\u0435\u0442\u0435, \u0430 \u043e\u0434\u043d\u043e\u0433\u043e \u043a\u0440\u0443\u043f\u043d\u043e\u0433\u043e \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f \u000d\u000a\u043f\u0440\u043e\u0438\u043d\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043b \u043e\u0431 \u044d\u0442\u043e\u043c \u0435\u0433\u043e \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a. \u0417\u0430\u043f\u0440\u0435\u0442 \u043a\u043e\u0441\u043d\u0435\u0442\u0441\u044f \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b, \u000d\u000a\u043f\u043e\u0431\u043e\u0447\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u0430 \u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0438 \u043c\u0435\u0434\u0438 \u0438 \u0446\u0438\u043d\u043a\u0430, \u000d\u000a\u0438 \u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u043e\u0434\u043b\u0438\u0442\u044c\u0441\u044f \u0434\u043e \u043a\u043e\u043d\u0446\u0430 \u0433\u043e\u0434\u0430.\u000a\u000d\u000a\u0426\u0435\u043d\u044b \u043d\u0430 \u0441\u0435\u0440\u043d\u0443\u044e \u043a\u0438\u0441\u043b\u043e\u0442\u0443 \u0440\u0430\u0441\u0442\u0443\u0442, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u000d\u000a\u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u0435 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0441\u0435\u0440\u044b \u0438\u0437 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u043b\u0438\u0432\u0430, \u0433\u0434\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u0434\u043e \u0442\u0440\u0435\u0442\u0438 \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043e\u0431\u044a\u0435\u043c\u0430 \u0441\u0435\u0440\u044b \u043a\u0430\u043a \u043f\u043e\u0431\u043e\u0447\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u0430 \u000d\u000a\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043d\u0435\u0444\u0442\u0438 \u0438 \u0433\u0430\u0437\u0430.\u000a\u000d\u000a\u041f\u043e\u043c\u0438\u043c\u043e \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0438 \u0441\u0435\u0440\u043d\u0430\u044f \u043a\u0438\u0441\u043b\u043e\u0442\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u043e \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043f\u0440\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435 \u043f\u043b\u0430\u0441\u0442\u0438\u043a\u043e\u0432 \u000d\u000a\u0438 \u0443\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0439, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u041a\u041d\u0420, \u0432\u0432\u043e\u0434\u044f \u000d\u000a\u0437\u0430\u043f\u0440\u0435\u0442, \u0437\u0430\u0431\u043e\u0442\u0438\u0442\u0441\u044f \u043e \u043f\u0440\u043e\u0434\u043e\u0432\u043e\u043b\u044c\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438.\u000a\u000d\u000a\u041f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044f\u043c \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b, \u000d\u000a\u043f\u0440\u0435\u0436\u0434\u0435 \u0432\u0441\u0435\u0433\u043e \u0447\u0438\u043b\u0438\u0439\u0441\u043a\u0438\u043c \u043c\u0435\u0434\u0435\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u043c \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f\u043c, \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u044e\u0449\u0438\u043c \u0434\u043e \u043c\u0438\u043b\u043b\u0438\u043e\u043d\u0430 \u000d\u000a\u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434, \u0432\u044b\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0439 \u043e\u0431\u044a\u0435\u043c \u0441\u043b\u043e\u0436\u043d\u043e \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u0437\u0430\u043c\u0435\u0441\u0442\u0438\u0442\u044c. \u041a\u0438\u0442\u0430\u0439, \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435\u0440 \u0441\u0435\u0440\u043d\u043e\u0439 \u000d\u000a\u043a\u0438\u0441\u043b\u043e\u0442\u044b, \u0432 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u043e\u0442\u0433\u0440\u0443\u0437\u0438\u043b 4,65 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u000d\u000a\u0438\u0437 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 32% \u0438 15% \u043f\u043e\u0441\u0442\u0443\u043f\u0438\u043b\u0438 \u0432 \u0427\u0438\u043b\u0438 \u000d\u000a\u0438 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044e \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0444\u0438\u043d\u0430\u043d\u0441\u044b\u000d\u000aCATL \u0441\u043e\u0437\u0434\u0430\u043b\u0430 \u0434\u043e\u0447\u043a\u0443 \u043f\u043e \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u043c \u2028\u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e $4,4 \u043c\u043b\u0440\u0434\u000d\u000a\u0421\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u0431\u0443\u0434\u0443\u0442 \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u043d\u044b \u0437\u0430 \u0441\u0447\u0435\u0442 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u0430\u043a\u0446\u0438\u0439 \u043d\u0430 \u0440\u044b\u043d\u043a\u0435.\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0432 \u043c\u0438\u0440\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439, \u000d\u000aContemporary Amperex Technology Co. Ltd., \u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u043b \u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 \u043d\u043e\u0432\u043e\u0433\u043e \u0434\u043e\u0447\u0435\u0440\u043d\u0435\u0433\u043e \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0441 \u0443\u0441\u0442\u0430\u0432\u043d\u044b\u043c \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u043e\u043c \u0432 30 \u043c\u043b\u0440\u0434 \u000d\u000a\u044e\u0430\u043d\u0435\u0439 ($4,4 \u043c\u043b\u0440\u0434). \u0415\u0433\u043e \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u0442\u044c \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u043c\u0438\u043d\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432, \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0438 \u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438.\u000a\u000d\u000a\u041f\u043e\u0434\u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0431\u0443\u0434\u0435\u0442 \u0432\u044b\u0441\u0442\u0443\u043f\u0430\u0442\u044c \u043a\u0430\u043a \u0438\u043d\u0432\u0435\u0441\u0442 \u000d\u000a\u0438 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 CATL \u0434\u043b\u044f \u0434\u043e\u0431\u044b\u0447\u0438 \u000d\u000a\u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445 \u0441 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u000d\u000a\u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u043c\u044b\u0445 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u044d\u043d\u0435\u0440\u0433\u0438\u0438. \u041e\u043d\u043e \u000d\u000a\u043a\u043e\u043d\u0441\u043e\u043b\u0438\u0434\u0438\u0440\u0443\u0435\u0442 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0435 \u0430\u043a\u0442\u0438\u0432\u044b \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0438 \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u043d\u043e \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u0442\u044c \u0434\u043e\u0431\u044b\u0447\u0443 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u000d\u000a\u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u044b.\u000a\u000d\u000a\u0420\u0430\u043d\u0435\u0435 CATL \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u043b\u0430 \u043e\u0441\u043d\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u2028\u000d\u000a\u0438 \u044d\u043a\u0441 \u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u044f \u0441\u043e\u0432\u0435\u0442\u0430 \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440\u043e\u0432 \u000d\u000aZijin Mining Group Co. Ltd \u0427\u044d\u043d\u044c \u0426\u0437\u0438\u043d\u0445\u044d \u000d\u000a\u0432 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u0441\u043e\u0432\u0435\u0442\u043d\u0438\u043a\u0430 \u0434\u043b\u044f \u0441\u0432\u043e\u0435\u0433\u043e \u0440\u0430\u0441\u0442\u0443\u0449\u0435\u0433\u043e \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0433\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u0430.\u000d\u000a15 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c #\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u041a\u0438\u0442\u0430\u044f \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u2028\u000d\u000a\u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0442\u044c \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u044e\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043d\u0430\u043f\u043e\u043c\u043d\u0438\u043b \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c \u0441\u0438\u043b\u043e\u0432\u044b\u0445 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u043e \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0438\u0437\u0431\u0435\u0433\u0430\u0442\u044c \u000d\u000a\u0447\u0440\u0435\u0437\u043c\u0435\u0440\u043d\u043e\u0433\u043e \u0440\u043e\u0441\u0442\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0442\u044c \u0446\u0435\u043d\u043e\u0432\u044b\u0435 \u0432\u043e\u0439\u043d\u044b.\u000d\u000a\u041d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432 \u041a\u041d\u0420, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0438 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439, \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u043b\u0438\u0441\u044c \u000d\u000a\u0441 16 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c\u0438 \u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u0434\u043b\u044f \u000d\u000a\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439. \u0422\u0435\u043c\u043e\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0438 \u0441\u0442\u0430\u043b\u0438 \u000d\u000a\u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0435 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0438 \u0437\u0430\u0449\u0438\u0442\u0430 \u000d\u000a\u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u043e\u0439 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u0440\u0430\u0437\u0443\u043c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0437\u0430 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435\u043c \u043e\u0442\u0440\u0430\u0441\u043b\u0438.\u000a\u000d\u000a\u0412 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u043c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u0430 \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f, \u0447\u0442\u043e \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u043e\u0441\u043e\u0437\u043d\u0430\u0432\u0430\u0442\u044c \u0432\u0430\u0436\u043d\u043e\u0441\u0442\u044c \u000d\u000a\u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043d\u0435\u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u000d\u000a\u043e\u0431\u043e\u0433\u0430\u0449\u0435\u043d\u0438\u044e \u0438 \u043d\u0435\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0449\u0435\u0439 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u0438. \u000d\u000a\u0422\u0430\u043a\u0436\u0435 \u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0440\u0435\u043a\u043b\u0430\u043c\u0443 \u043c\u0435\u0441\u0442\u043d\u044b\u0445 \u000d\u000a\u043e\u0440\u0433\u0430\u043d\u043e\u0432 \u0432\u043b\u0430\u0441\u0442\u0438 \u043f\u043e \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044e \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u000d\u000a\u0432 \u044d\u0442\u043e\u0442 \u0441\u0435\u043a\u0442\u043e\u0440. \u0410\u043a\u0446\u0438\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u0440\u0435\u0437\u043a\u043e \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u0432 \u043f\u044f\u0442\u043d\u0438\u0446\u0443, \u000d\u000a\u0432 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438, \u0431\u0443\u043c\u0430\u0433\u0438 CATL \u043f\u043e\u0434\u0441\u043a\u043e\u0447\u0438\u043b\u0438 \u043d\u0430 7,4% \u000d\u000a\u0432 \u043c\u0430\u0442\u0435\u0440\u0438\u043a\u043e\u0432\u043e\u043c \u041a\u0438\u0442\u0430\u0435 \u0438 \u043d\u0430 7% \u0432 \u0413\u043e\u043d\u043a\u043e\u043d\u0433\u0435.\u000a\u000d\u000a\u0411\u0435\u0441\u0435\u0434\u0430 \u043f\u0440\u043e\u0448\u043b\u0430 \u0432 \u0431\u043e\u043b\u0435\u0435 \u0441\u0442\u0440\u043e\u0433\u043e\u043c \u0442\u043e\u043d\u0435, \u0447\u0435\u043c \u000d\u000a\u043d\u0430 \u0430\u043d\u0430\u043b\u043e\u0433\u0438\u0447\u043d\u043e\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0435 \u0432 \u044f\u043d\u0432\u0430\u0440\u0435, \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u000d\u000aBloomberg. \u041e\u0442\u0440\u0430\u0441\u043b\u044c \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0445\u043e\u0440\u043e\u0448\u0438\u0435 \u000d\u000a\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0439 \u000d\u000a\u044d\u043d\u0435\u0440\u0433\u043e\u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u0441\u0442\u0438\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442 \u0441\u043f\u0440\u043e\u0441 \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u0438 \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c. \u041d\u0430\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0440\u0430\u0434\u0443\u0436\u043d\u044b. \u041e\u0434\u043d\u0430\u043a\u043e \u044d\u0442\u0430 \u000d\u000a\u0442\u0435\u043d\u0434\u0435\u043d\u0446\u0438\u044f \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u0432 \u041f\u0435\u043a\u0438\u043d\u0435 \u043e\u043f\u0430\u0441\u0435\u043d\u0438\u044f \u000d\u000a\u043f\u0435\u0440\u0435\u0433\u0440\u0435\u0432\u0430 \u0440\u044b\u043d\u043a\u0430, \u043e\u0442\u0447\u0430\u0441\u0442\u0438 \u0438\u0437-\u0437\u0430 \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u0435\u0439 \u000d\u000a\u0441 \u0446\u0438\u043a\u043b\u043e\u043c \u0441\u043e\u043b\u043d\u0435\u0447\u043d\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u043f\u043e\u0441\u043b\u0435 2021 \u0433\u043e\u0434\u0430, \u000d\u000a\u043a\u043e\u0433\u0434\u0430 \u0440\u0435\u0437\u043a\u0438\u0439 \u0440\u043e\u0441\u0442 \u0441\u043f\u0440\u043e\u0441\u0430 \u0432\u044b\u0437\u0432\u0430\u043b \u0432\u043e\u043b\u043d\u0443 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0432 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u043c \u0438\u0442\u043e\u0433\u0435 \u043f\u0440\u0438\u0432\u0435\u043b\u0430 \u000d\u000a\u043a \u043f\u0435\u0440\u0435\u0438\u0437\u0431\u044b\u0442\u043a\u0443 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0438 \u043e\u0431\u0432\u0430\u043b\u0443 \u0446\u0435\u043d. \u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u000d\u000a\u0422\u0440\u0438 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u000d\u000a\u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u043b\u0438\u0442\u0438\u044f \u0438\u0437 \u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435 \u000d\u000a\u041f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0432\u0430\u0436\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0441\u044b\u0440\u044c\u044f \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u0444\u0435\u0432\u0440\u0430\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u043f\u0440\u0435\u0442\u0430 \u0432\u043b\u0430\u0441\u0442\u0435\u0439.\u000d\u000a13 \u0430\u043f\u0440\u0435\u043b\u044f \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 Sinomine \u000d\u000aResource \u0438 Chengxin Lithium, \u0430 14 \u0430\u043f\u0440\u0435\u043b\u044f \u043e\u0434\u0438\u043d \u000d\u000a\u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043b\u0438\u0442\u0438\u044f \u0432 \u0410\u0444\u0440\u0438\u043a\u0435 \u000d\u000aYahua Industrial Group, \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 Reuters. Yahua \u000d\u000a\u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0434\u0432\u0430 \u043c\u0435\u0441\u044f\u0446\u0430 \u043d\u0430\u0437\u0430\u0434, \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u0432\u0432\u0435\u0434\u0435\u043d\u0438\u044f \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435 \u000d\u000a\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439, \u0438 \u0442\u0435\u043f\u0435\u0440\u044c \u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e \u0435\u0433\u043e \u000d\u000a\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0438\u0432\u0430\u0435\u0442. \u041a\u0432\u043e\u0442\u0430 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043d\u0430 \u043d\u0430 \u043f\u043e\u043b\u0433\u043e\u0434\u0430 \u000d\u000a\u0438 \u0431\u0443\u0434\u0435\u0442 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0439 \u0434\u043b\u044f \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u044b \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u041a\u0430\u043c\u0430\u0442\u0438\u0432\u0438, \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e \u000d\u000a\u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000d\u000a\u0412 \u0444\u0435\u0432\u0440\u0430\u043b\u0435 \u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u000d\u000a\u0432\u0441\u0435\u0445 \u0432\u0438\u0434\u043e\u0432 \u0441\u044b\u0440\u044c\u044f \u0438 \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u0445 \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u043e\u0432, \u000d\u000a\u0441\u043e\u0441\u043b\u0430\u0432\u0448\u0438\u0441\u044c \u043d\u0430 \u043c\u043d\u043e\u0433\u043e\u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0435 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f. \u000d\u000a\u0412 \u043d\u0430\u0447\u0430\u043b\u0435 \u0430\u043f\u0440\u0435\u043b\u044f \u0432\u043b\u0430\u0441\u0442\u0438 \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0438 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c \u043e \u0432\u0432\u0435\u0434\u0435\u043d\u0438\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0445 \u043a\u0432\u043e\u0442 \u000d\u000a\u043d\u0430 \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u0435 \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u044b \u0438 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u043c \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0438 \u043e\u0431\u044a\u0435\u043c\u043e\u0432 \u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438. \u000d\u000a\u0412 2025 \u0433\u043e\u0434\u0443 \u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0432 \u041a\u0438\u0442\u0430\u0439 \u000d\u000a1,13 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043b\u0438\u0442\u0438\u0439\u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0435\u0433\u043e \u0441\u043f\u043e\u0434\u0443\u043c\u0435\u043d\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0430, \u0447\u0442\u043e \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 15% \u043e\u0442 \u0432\u0441\u0435\u0433\u043e \u000d\u000a\u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u044f \u0432 \u041a\u041d\u0420.\u000d\u000a16 17","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 10\u201324 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0435 \u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u0432 \u041a\u041d\u0420 \u2028\u000d\u000a\u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0441\u0442\u0438 \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u043d\u0430 3,7% \u0434\u043e 2035 \u0433\u043e\u0434\u0430\u000d\u000a\u0422\u0430\u043a\u043e\u0439 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043e\u0431\u043d\u0430\u0440\u043e\u0434\u043e\u0432\u0430\u043b \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0441\u044b\u0440\u044c\u0435\u0432\u043e\u0439 \u0433\u0438\u0433\u0430\u043d\u0442 Minmetals.\u000d\u000a\u041f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0435 \u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u000d\u000a\u043d\u0430 \u0432\u0435\u0434\u0443\u0449\u0435\u043c \u0440\u044b\u043d\u043a\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0432 \u041a\u0438\u0442\u0430\u0435 \u000d\u000a\u043d\u0435 \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u043e\u0432 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u043f\u0438\u043a\u0430 \u000d\u000a\u0438 \u043c\u043e\u0436\u0435\u0442 \u0440\u0430\u0441\u0442\u0438 \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u043d\u0430 3,7% \u0432 \u0433\u043e\u0434 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u0433\u043e \u0434\u0435\u0441\u044f\u0442\u0438\u043b\u0435\u0442\u0438\u044f.\u000a\u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0432\u043e \u0432\u0442\u043e\u0440\u043d\u0438\u043a, 14 \u0430\u043f\u0440\u0435\u043b\u044f, \u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u043d\u0430 \u0412\u0441\u0435\u043c\u0438\u0440\u043d\u043e\u0439 \u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u0438 \u043f\u043e \u043c\u0435\u0434\u0438 \u0432 \u0421\u0430\u043d\u0442\u044c\u044f\u0433\u043e \u000d\u000a\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u043f\u043e \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f\u043c \u0440\u044b\u043d\u043a\u0430 \u0432 Minmetals \u000d\u000aNon-Ferrous \u0426\u0437\u043e \u0425\u0430\u043e\u044d\u043d\u044c.\u000a\u000d\u000a\u0420\u043e\u0441\u0442 \u0441\u043f\u0440\u043e\u0441\u0430 \u0432 \u041a\u0438\u0442\u0430\u0435 \u0431\u0443\u0434\u0435\u0442 \u0432 2026 \u0433\u043e\u0434\u0443 \u000d\u000a\u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043d\u0438\u0436\u0435 \u0438 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 1%, \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u000d\u000a\u0430\u043d\u0430\u043b\u0438\u0442\u0438\u043a, \u0441\u043e\u0441\u043b\u0430\u0432\u0448\u0438\u0441\u044c \u043d\u0430 \u0437\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u0435 \u0442\u0435\u043c\u043f\u043e\u0432 \u000d\u000a\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430, \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0432 \u043e\u0431\u043b\u0430\u0441\u0442\u0438 \u000d\u000a\u044d\u043d\u0435\u0440\u0433\u043e\u0435\u043c\u043a\u043e\u0439 \u0441\u043e\u043b\u043d\u0435\u0447\u043d\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438, \u0438 \u0432\u044b\u0441\u043e\u043a\u0438\u0435 \u000d\u000a\u0446\u0435\u043d\u044b \u043d\u0430 \u043c\u0435\u0434\u044c.\u000a\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u00ab\u043d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u043e\u043c\u0443\u00bb \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044e \u000d\u000aMinmetals, \u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0435 \u043c\u0435\u0434\u0438 \u0432 \u041a\u0438\u0442\u0430\u0435 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0441\u0442\u0438 \u000d\u000a\u043d\u0430 3,7% \u0432 \u0433\u043e\u0434 \u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0435\u0442 22,95 \u043c\u043b\u043d \u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u0442\u043e\u043d\u043d \u043a 2035 \u0433\u043e\u0434\u0443, \u0447\u0442\u043e \u043d\u0430 43% \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u000d\u000a\u0432 2025 \u0433\u043e\u0434\u0443 (16 \u043c\u043b\u043d \u0442\u043e\u043d\u043d).\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000aTsingshan \u0438\u0449\u0435\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u0430 \u0434\u043b\u044f \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0433\u043e \u0437\u0430\u0432\u043e\u0434\u0430 \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0437\u0430 $3 \u043c\u043b\u0440\u0434\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0441\u0434\u0435\u043b\u043a\u0435 \u0445\u0435\u0434\u0436\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0440\u0438\u0441\u043a\u043e\u0432 \u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438.\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Tsingshan, \u0441\u044b\u0433\u0440\u0430\u0432\u0448\u0430\u044f \u043a\u043b\u044e\u0447\u0435\u0432\u0443\u044e \u0440\u043e\u043b\u044c \u000d\u000a\u0432 \u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0438 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u043a\u0430\u043a \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u044e\u0449\u0435\u0433\u043e \u000d\u000a\u0438\u0433\u0440\u043e\u043a\u0430 \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u043d\u0438\u043a\u0435\u043b\u044f, \u043d\u0430\u0434\u0435\u0435\u0442\u0441\u044f \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u044c \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0442\u0440\u0435\u0439\u0434\u0435\u0440\u043e\u0432 \u000d\u000a\u0441\u044b\u0440\u044c\u044f Mercuria Energy Group, Glencore Plc \u000d\u000a\u0438 Trafigura Group \u0432 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0437\u0430\u0432\u043e\u0434\u0430 \u000d\u000a\u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u043d\u0430 \u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u043e\u043c \u000d\u000a\u043e\u0441\u0442\u0440\u043e\u0432\u0435 \u0425\u0430\u043b\u043c\u0430\u0445\u0435\u0440\u0430. \u041f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u043d\u0430\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u000d\u000a\u0432 \u043f\u0440\u043e\u0434\u0432\u0438\u043d\u0443\u0442\u043e\u0439 \u0441\u0442\u0430\u0434\u0438\u0438, \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 Bloomberg.\u000a\u000d\u000a\u0412 \u0441\u0432\u043e\u0435 \u0432\u0440\u0435\u043c\u044f, \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0435 \u043f\u0430\u0440\u043a\u0438 \u000d\u000a\u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438 \u043d\u0430 \u0421\u0443\u043b\u0430\u0432\u0435\u0441\u0438 \u0438 \u0412\u044d\u0434\u0430 \u0411\u044d\u0439 \u0432 \u0421\u0435\u0432\u0435\u0440\u043d\u043e\u043c \u000d\u000a\u041c\u0430\u043b\u0443\u043a\u0443, Tsingshan \u043a\u043e\u043e\u043f\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043b\u0430\u0441\u044c \u000d\u000a\u0441 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c\u0438 \u043b\u0438\u0431\u043e \u0441 \u043c\u0435\u0441\u0442\u043d\u044b\u043c\u0438 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c\u0438. \u000d\u000a\u0422\u0435\u043f\u0435\u0440\u044c \u0436\u0435, \u043f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0430, \u000d\u000a\u00ab\u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432\u043b\u0438\u044f\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u043f\u0430\u0434\u043d\u044b\u0445 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432 \u000d\u000a\u0441 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u043c \u0432\u0438\u0434\u0435\u043d\u0438\u0435\u043c \u0438 \u043e\u0431\u0448\u0438\u0440\u043d\u043e\u0439 \u043a\u043b\u0438\u0435\u043d\u0442\u0441\u043a\u043e\u0439 \u000d\u000a\u0431\u0430\u0437\u043e\u0439 \u043f\u043e\u043c\u043e\u0436\u0435\u0442 Tsingshan \u0437\u0430\u0440\u0443\u0447\u0438\u0442\u044c\u0441\u044f \u000d\u000a\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u043e\u0439 \u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0440\u0430\u0437\u043e\u0447\u0430\u0440\u043e\u0432\u0430\u043b\u043e\u0441\u044c \u0432 \u043c\u0435\u0441\u0442\u043d\u044b\u0445 \u000d\u000a\u043c\u0438\u043b\u043b\u0438\u0430\u0440\u0434\u0435\u0440\u0430\u0445 \u0438\u0437 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u00bb.\u000a\u000d\u000a\u0410 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u043c \u0442\u0440\u0435\u0439\u0434\u0435\u0440\u0430\u043c \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u0438\u0435 \u000d\u000a\u043c\u0438\u043d\u043e\u0440\u0438\u0442\u0430\u0440\u043d\u044b\u0445 \u0434\u043e\u043b\u0435\u0439 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442 \u0434\u043e\u0441\u0442\u0443\u043f \u000d\u000a\u043a \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f, \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u044f\u0449\u0435\u0433\u043e \u000d\u000a800 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u043e, \u0432 \u0442\u043e \u0432\u0440\u0435\u043c\u044f \u000d\u000a\u043a\u0430\u043a \u043a\u0440\u0438\u0437\u0438\u0441 \u0432\u043e\u043a\u0440\u0443\u0433 \u0418\u0440\u0430\u043d\u0430 \u043d\u0430\u0440\u0443\u0448\u0438\u043b \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0438\u0437 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0440\u0435\u0433\u0438\u043e\u043d\u0430, \u000d\u000a\u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043e\u043a\u043e\u043b\u043e 10% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Emirates Global \u000d\u000aAluminium PJSC, \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u000d\u000a\u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435, \u0437\u0430\u044f\u0432\u0438\u043b\u0430, \u0447\u0442\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u000d\u000a\u043e\u0431\u044a\u0435\u043c\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043d\u0430 \u0435\u0435 \u0437\u0430\u0432\u043e\u0434\u0435 \u0432 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u0438\u0440\u0430\u043d\u0441\u043a\u043e\u0439 \u0430\u0442\u0430\u043a\u0438 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043d\u044f\u0442\u044c \u0434\u043e \u0433\u043e\u0434\u0430.\u000d\u000a17 17"]